(window.GIM_TS=window.GIM_TS||{})["Nazir.4"]={"from":96,"a":[["\u0003אמר ר' יוסי:\u0004 מעתה \u0003יאמרו מאיר שכב\u0004 (מת), \u0003יהודה כעס, יוסי שתק\u0004 ולא הגיב — אם כן \u0003תורה מה תהא עליה? אמר ר' יוסי: לא נצרכה\u0004 להיאמר שמגלח \"על המת\" \u0003אלא למת שאין עליו כזית בשר\u0004 שלמרות כן מגלח. ומקשים: \u0003ועדיין יאמר: על אבר ממנו\u0004 מן המת \u0003מגלח\u0004 כפי ששנינו במשנה, ואף אם אין בו כזית, \u0003על כולו לא כל שכן\u0004 שמגלח אף אם אין בו כזית בשר?!","\u0003אלא\u0004 יש לפרש זאת \u0003כדאמר\u0004 \u0005[כפי שאמר\u0006\u0005]\u0006 \u0003ר' יוחנן\u0004 לענין אחר: \u0003לא נצרכה אלא לנפל ש\u0004עדיין \u0003לא נתקשרו אבריו בגידין,\u0004 כלומר, שהוא עדיין רק בשר בלבד ואין בו גידים ועצמות. \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 כשאמרה משנה שעל המת מגלח, נאמר כי מדובר \u0003בנפל\u0004 שעדיין \u0003לא נתקשרו אבריו בגידין,\u0004 שאף על פי שאין אבר ממנו מטמא, לפי שאין בו גידים ועצמות, מכל מקום הוא עצמו מטמא.","\u0003רבא אמר\u0004 הסבר אחר: \u0003לא נצרכה אלא לרוב בניינו ו\u0004כן \u0003לרוב מניינו\u0004 של מת קטן מאד, אף \u0003שאין בהן\u0004 בכולם \u0003רובע עצמות.\u0004 שכיון שהוא רוב בנין או רוב מנין של מת, דינו כמת שלם, ואי אפשר היה ללמוד זאת משיעור טומאה של חלק ממנו.","שנינו \u0003\"על כזית מת ועל כזית נצל\".\u0004 מסבירים: \u0003ואיזהו נצל —\u0004 \u0003בשר המת ש\u0004נימוח ואחר כך \u0003קרש, ומוהל\u0004 ליחה שיוצאת מן המת \u0003שהרתיח,\u0004 שהתחיל לתסוס, והתקשה אחר כך.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר\u0006\u0005]?\u0006 \u0003אילימא דלא ידעינן דדידיה\u0004 \u0005[אם תאמר\u0006 במקרה שאין אנו יודעים ששלו\u0005]\u0006 \u0003הוא,\u0004 כלומר, שאין אנחנו בטוחים שדבר זה יצא מן המת, \u0003כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 הוא \u0003קרש מאי הוי\u0004 \u0005[מה יש\u0006\u0005]\u0006 מה נוסף על ידי כך? \u0003אלא\u0004 תאמר \u0003דידעינן דדידיה\u0004 \u0005[שאנו יודעים ששלו\u0006\u0005]\u0006 \u0003הוא\u0004 מן המת יצא, אם כן \u0003אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003לא קרש\u0004 בכל זאת יהא טמא!","\u0003אמר ר' ירמיה,\u0004 כך צריך להסביר: מדובר \u0003בסתם\u0004 שאנו יודעים שמן המת הוא, אלא שאין אנו יודעים אם היה זה חלק שמטמא. ולכן בודקים את הדבר, \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 בסוף הדבר הזה \u0003קרש\u0004 \u0005[מתקרש\u0006\u0005],\u0006 יש להניח ש\u0003מוהל הוא,\u0004 ליחה מן המת המטמאת, ואם \u0003לא קרש\u0004 יש לומר \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003כיחו וניעו הוא,\u0004 כלומר, רוק וליחה שיצאו ממנו, ובאלו אין טומאת מת.","אגב האיזכור של טומאת נצל \u0003בעא מיניה\u0004 \u0005[שאל אותו\u0006\u0005]\u0006 \u0003אביי מרבה:\u0004 האם \u0003יש נצל לבהמה או אין נצל לבהמה?\u0004 כלומר, האם בדין טומאת נבלת בהמה יש גם כן דין נצל שמטמא כנבילה עצמה, או לא. וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים\u0006\u0005]\u0006 \u0003גמירי\u0004 \u0005[למודים אנו\u0006 במסורת\u0005]\u0006 דין \u0003נצל דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 \u0003מאדם, אבל\u0004 זה \u0003דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 \u0003מבהמה —\u0004 \u0003לא,\u0004 אינו נחשב כנצל ואין בו טומאת נבילה. \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003לא שנא\u0004 \u0005[שונה\u0006\u0005],\u0006 שדין הנצל בכלל הוא כדין הבשר עצמו?","ומעירים: \u0003הניחא\u0004 \u0005[זה נוח\u0006\u0005],\u0006 כלומר, אין זו כלל בעיה \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת מי שאומר\u0005]\u0006 \u0003טומאה חמורה\u0004 של נבילה, שתטמא אדם במגע ובמשא, היא \u0003עד\u0004 (כל עוד) הנבילה ראויה לאכילה \u0003לגר\u0004 (כלומר, למאכל אדם), \u0003ו\u0004אילו \u0003טומאה קלה\u0004 לטמא רק אוכלים במגע, נשארת בנבילה \u0003עד\u0004 שתיפסל \u0003ל\u0004אכילת \u0003כלב\u0004 — \u0003שפיר\u0004 \u0005[יפה\u0006\u0005],\u0006 כי לשיטה זו אין דין נצל לבהמה, שהרי בשעה שנימוח הבשר ודאי אינו ראוי עוד לאכילת אדם.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת מי שאומר\u0005]\u0006 שגם \u0003טומאה חמורה\u0004 נשארת בנבילה \u0003עד\u0004 שתיפסל \u0003ל\u0004אכילת \u0003כלב, מאי איכא למימר\u0004 \u0005[מה יש לומר\u0006\u0005]?\u0006 כלומר, לשיטה זו עומדת השאלה, שהרי נצל זה מן הסתם עדיין ראוי הוא לאכילת כלב. ולפיכך יש לשאול: האם יש דין נצל בבהמה, ונצל זה מטמא. או שמא כיון שנימוח שוב אינו נחשב כבשר הנבילה כלל?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 תשובה לדבר ממה ששנינו: חלב נבלת בהמה ש\u0003המחוהו\u0004 (המיסו אותו) \u0003באור\u0004 (אש) — עדיין הוא \u0003טמא,\u0004 ואולם אם נמס \u0003בחמה,\u0004 שנפגם טעמו — \u0003טהור. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר לפי השיטה שנבילה מטמאה \u0003עד\u0004 שתיפסל \u0003ל\u0004אכילת \u0003כלב,\u0004 כי יש נצל לבהמה, אם כן \u0003אפילו\u0004 חלב שנמס \u0003בחמה נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 יהא טמא! שאף שנפגם טעמו, מכל מקום ראוי הוא עדיין לאכילת כלב.","ומשיבים: \u0003אימת ממחי ליה\u0004 \u0005[מתי הוא נמס\u0006\u0005]\u0006 — \u0003בתר דאסרוח\u0004 \u0005[אחר שהסריח\u0006\u0005]\u0006 ומשום כך השליכוהו, ונמס \u0003בחמה,\u0004 אולם \u0003כיון דאסרח\u0004 \u0005[שהסריח\u0006\u0005] —\u0006 \u0003הוה ליה\u0004 \u0005[הרי נעשה\u0006\u0005]\u0006 כבר \u0003עפר,\u0004 שבטלה ממנו טומאה כל עיקר, שלאחר שנימוח אינו ראוי עוד אף לאכילת כלב. ואין מכאן ראיה.","אגב הדברים הללו מביאים דיון בנושא המתקשר אליהם. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הנצוק —\u0004 \u0003טהור.\u0004 כלומר, אם יוצק אדם נוזל מכלי אחד למשנהו — אין אנו אומרים שסילון היציקה הנוזל מחבר בין הכלי שלמטה והכלי שלמעלה. ולכן אם היה הכלי העליון ומה שבתוכו טהור — אינו נטמא גם אם הכלי התחתון שאליו נצוק הנוזל טמא, שאין סילון של נוזלים מהווה חיבור לכל דבר.","\u0003חוץ מדבש הזיפים\u0004 (סוג דבש סמיך מאד) \u0003ו\u0004כן \u0003הצפיחית\u0004 (קמח מעורב בדבש), שכיון שהם סמיכים מאד הרי אינם נחשבים עוד כנוזל, אלא כעין מוצק רך, והריהם גוף אחד המחבר בין שני הכלים לענין טומאה."],["\u0003בית שמאי אומרים: אף\u0004 הניצוק של \u0003המקפה\u0004 (תבשיל) \u0003של גריסין\u0004 (פולים שנכתשו ונשברו במכתש) \u0003ושל פול\u0004 (שלם) גם כן נחשב לחיבור \u0003מפני שהיא סולדת\u0004 (חוזרת) \u0003לאחוריה,\u0004 שהרי כאשר פוסקים לצקת מקפה זו רואים שחלק מן הניצוק חוזר לאחוריו, ואם כן הניצוק צריך להיחשב כיחידה אחת.","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רמי בר חמא\u0004 שאלה זו: האם \u0003יש נצוק לאוכלין או אין נצוק לאוכלין.\u0004 כלומר מיני אוכל, כגון שומן, שהמסו אותם, האם ניצוק הוא חיבור בהם? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים\u0006\u0005]\u0006 שדבש הזיפים והצפיחית מהווים חיבור \u0003משום דאית בהו רירי\u0004 \u0005[שיש בהם רירים\u0006\u0005],\u0006 \u0003והני לית בהו רירי\u0004 \u0005[ואלה,\u0006 אוכלים, אין בהם רירים\u0005].\u0006 \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 הטעם שדבש הזיפים והצפיחית \u0003משום דסמיכין\u0004 \u0005[שסמיכים\u0006\u0005]\u0006 \u0003הוא, והכא הא\u0004 \u0005[וכאן הרי\u0006\u0005]\u0006 אוכלים שהומסו \u0003סמיכים הוא\u0004 \u0005[הם\u0006\u0005]?\u0006","\u0003אמר רבא תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לשאלה ממה ששנינו: \u0003חלב המת שהוא שלם\u0004 ויש בו כזית \u0003והתיכו\u0004 — הריהו \u0003טמא, היה\u0004 החלב \u0003מפורד\u0004 מתחילתו לחלקים קטנים מכזית שלא היה בהם כדי לטמא, \u0003והתיכו\u0004 ונצטרף יחד לכזית — \u0003טהור. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר ש\u0003אין נצוק לאוכלין,\u0004 גם אם היה \u0003שלם והתיכו נמי ליטהר\u0004 \u0005[גם כן שייטהר\u0006\u0005]\u0006 שהרי נעשה נוזל ומתפשט ממקום למקום במחבת, ואם אינו חיבור — יחשב כל חלק שנוזל לעצמו, ויבטל שיעור כזית!","\u0003אמר ר' זירא: אנא\u0004 \u0005[אני\u0006\u0005]\u0006 \u0003ומר בריה\u0004 \u0005[בנו\u0006\u0005]\u0006 של \u0003רבינא תרגימנא\u0004 \u0005[תרגמנו,\u0006 הסברנו\u0005]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים\u0006\u0005] —\u0006 \u0003כגון דבהדי דמרתח ליה\u0004 \u0005[שבזמן שהוא מרתיח אותו\u0006\u0005]\u0006 \u0003סליק עמודא דנורא לפומיה דמנא וקרש\u0004 \u0005[עולה עמוד האש\u0006 שמתחת לכלי לפי הכלי, ונקרש\u0005]\u0006 שם החלב, \u0003דאיתיה כולא גבי הדדי\u0004 \u0005[שנמצא כולו יחד\u0006\u0005]\u0006 ואין כאן ניצוק.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רבינא לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לשאלה האם יש ניצוק באוכלים, ממה ששנינו: \u0003בית שמאי אומרים: אף המקפה של גריסין ושל פול\u0004 מטמאים בניצוק \u0003מפני שהן סולדין לאחוריהן,\u0004 משמע שבכך תלוי הדבר. אמר לו: \u0003מידי איריא\u0004 \u0005[\u0006וכי הדברים שייכים זה לזה\u0005]?\u0006 \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 באוכלים, צד הספק לומר שיהא בהם ניצוק הוא \u0003משום דסמיכין\u0004 \u0005[ש\u0006הם סמיכים\u0005].\u0006 \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 במקפה, יש לומר שמהווה חיבור \u0003משום רירי\u0004 \u0005[הרירים\u0006\u0005]\u0006 שיש בה, ולכן אין ניצוק מחבר אלא בדבש, וכיוצא בו מקפה, שיש בהם רירים, ולא באוכלים.","שנינו במשנה: \u0003\"ועל מלא תרווד רקב\". ו\u0004מבררים \u0003כמה שיעורו\u0004 של מלוא תרווד זה? \u0003חזקיה אמר: מלא פיסת\u0004 (כף) \u0003היד, ר' יוחנן אמר: מלא חפניו\u0004 (כל מה שנכנס בכף היד עם אצבעותיה). ומביאים: \u0003תנן\u0004 \u0005[שנינו\u0006\u0005]:\u0006 \u0003מלא תרווד רקב שאמרו ישנו\u0004 (יש בו) שיעור כל שנכנס \u0003מעיקר\u0004 משורש ה\u0003אצבעות ולמעלה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: מלא חפניו.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ר' יוחנן —\u0004 \u0003הוא\u0004 ש\u0003אמר כרבנן\u0004 \u0005[כ\u0006דברי חכמים\u0005],\u0006 \u0003אלא חזקיה כמאן\u0004 \u0005[כמי\u0006\u0005]\u0006 אמר? הלא דבריו הם \u0003לא כר' מאיר ולא כרבנן\u0004 \u0005[כחכמים\u0006\u0005],\u0006 שהרי לדעת חכמים — מלוא חפניו, ולדעת ר' מאיר מדובר רק במה שבתוך האצבעות עצמן בלבד, ולא כדברי חזקיה — במה שבכף היד! \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 השיעור שהגדירו חזקיה \u0003מלא פיסת היד, ו\u0004השיעור שהגדירו ר' מאיר \u0003מלא קשרי אצבעותיו למעלה\u0004 מפיסת היד — \u0003חד שיעורא\u0004 \u0005[שיעור אחד\u0006\u0005]\u0006 \u0003הוא,\u0004 שיש בהם אותה כמות.","ועל עצם ההנחה לפיה הקשו על חזקיה, \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב שימי בר אדא לרב פפא: ממאי דהאי\u0004 \u0005[ממה,\u0006 מנין, שזה\u0005]\u0006 שנאמר בדברי ר' מאיר \u0003מקשרי אצבעותיו ולמעלה\u0004 הכוונה היא \u0003ל\u0004כיוון \u0003ראש\u0004 האצבעות? \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 הכוונה היא \u0003למטה מדידיה\u0004 \u0005[ממנו\u0006\u0005]\u0006 לכיוון הזרוע, \u0003דהוה ליה\u0004 \u0005[שהרי הוא\u0006\u0005]\u0006 בדיוק מה שנאמר בדברי חזקיה \u0003מלא פיסת היד\u0004 ואין מקום כלל להקשות על חזקיה? לשאלה זו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006\u0005]\u0006 במקומה."],["שנינו במשנתנו שאחת הטומאות שהנזיר מגלח עליהן הוא מלוא תרווד רקב מן המת. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003איזהו מת שיש לו\u0004 תורת \u0003רקב,\u0004 כלומר, שהרקב שלו יש בו דין טומאה — \u0003מת שנקבר ערום בארון של שיש, או על גבי רצפה של אבנים —\u0004 \u0003זהו מת שיש לו רקב,\u0004 משום שכל הרקב שנמצא בוודאי בא מן המת. אבל אם \u0003נקבר בכסותו,\u0004 או נקבר \u0003בארון של עץ, או על גבי רצפה של לבנים —\u0004 \u0003זהו מת שאין לו רקב,\u0004 משום שיש לשער שיש בתוך הרקב הבא מן המת גם רקב הכסות, או העץ, או הלבנים שהתפוררו. ולמדנו במסורת שאין טומאת רקב המת אלא ביוצא מן המת לבדו, ולא בתערובת.","ובאותו ענין הוסיף ו\u0003אמר עולא: אין רקב אלא\u0004 זה \u0003הבא מן הבשר ומן הגידים ומן העצמות\u0004 של המת יחד, ולא מאחד מאלה לחוד. \u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003רבא לעולא:\u0004 שנינו \u0003רקב הבא מן הבשר —\u0004 \u0003טהור,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אם הוא בא \u0003מן העצם —\u0004 \u0003טמא, ואף על גב דליכא\u0004 \u0005[ואף על פי שאין\u0006\u0005]\u0006 בו מן ה\u0003בשר!\u0004 והשיב לו עולא: \u0003אימא הכי\u0004 \u0005[אמור כך\u0006\u0005]\u0006 ודייק אחרת: \u0003רקב הבא מן הבשר טהור, עד שיש עצם בבשר.\u0004","וחזר והקשה לו רבא: גם אם מפרשים כן, בכל זאת: \u0003הא ליכא\u0004 \u0005[הרי אין\u0006\u0005]\u0006 נזכרים כאן \u0003גידים,\u0004 שהרי לא מנה אותם, והלוא צריך שיהיה שם גם רקב מן הגידים! ענה לו: אין צורך לשנות במפורש גידים, שכן \u0003אי אפשר לבשר ולעצמות בלא גידים,\u0004 ואם יש שם בשר ועצם — יש גם גידים.","ועוד בענין זה של רקב המת \u0003אמר רב שמואל בר אבא אמר ר' יוחנן: שני מתים שקברן זה עם זה —\u0004 \u0003נעשו גלגלין זה לזה.\u0004 כלומר, יש דין תערובת ברקב שלהם. שכיון שאין הרקב ממת אחד לבדו, הרי זה כתערובת רקב אחר, ואינו מטמא. \u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 עליו \u0003רב נתן,\u0004 והרי שנינו: \u0003רקב הבא משני מתים\u0004 — \u0003טמא!\u0004","\u0003אמר רבא:\u0004 שם הכוונה היא \u0003שקברו\u0004 את \u0003זה בפני עצמו ו\u0004את \u0003זה בפני עצמו, והרקיבו\u0004 שניהם בנפרד, \u0003ועמדו\u0004 שניהם \u0003על מלא תרווד רקב,\u0004 ואז הם מטמאים כרקב מן המת, אף שאינו ממת אחד, כיון שמתחילה היה בהם דין רקב המת. אבל אם נרקבו יחד — נעשו כתערובת זה לגבי זה, ואין הרקב שלהם מטמא.","ועוד בענין זה של רקב המת \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 אם \u0003גזז שערו\u0004 של המת \u0003וקברו\u0004 (את השיער) \u0003עמו,\u0004 עם המת — \u0003נעשה לו\u0004 השיער \u0003גלגלין,\u0004 ושוב אין דנים את הרקב מן המת כמטמא. אגב ענין זה מביאים, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006\u0005]\u0006 במסכת אהלות: \u0003כל\u0004 שבגוף \u0003המת —\u0004 \u0003טמא, חוץ מן השינים והשער והצפורן\u0004 שאינם מטמאים כחלק מן המת. \u0003ובשעת חיבורן\u0004 למת — \u0003כולן טמאין.\u0004","ובבירורו של דין זה \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003חזקיה: שערו\u0004 של המת \u0003העומד לגלח, צפורן העומד ליגזז, מאי\u0004 \u0005[מה\u0006\u0005]\u0006 דינם? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים\u0006\u0005]:\u0006 \u0003כל העומד ליגזז —\u0004 \u0003כגזוז דמי\u0004 \u0005[נחשב\u0006\u0005]\u0006 ולכן ייחשבו אלה כנפרדים מגופו — ואינם מטמאים, \u0003או דלמא השתא מיהא הא\u0004 \u0005[שמא עכשיו על כל פנים הרי\u0006\u0005]\u0006 \u0003מחוברין\u0004 הם ומטמאים?","ושואלים: \u0003וניפשוט ליה\u0004 \u0005[ונפתור לו\u0006 לחזקיה\u0005]\u0006 את הבעיה \u0003מ\u0004מה שאמר \u0003רבה בר בר חנה:\u0004 גזז שערו וקברו עמו נעשה לו גלגלין. ונדייק מן הדברים כך: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שנעשה גלגלין \u0003משום\u0004 ש\u0003גזז\u0004 את השיער, \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אם \u0003לא גזז\u0004 ואפילו אם שיער זה עומד ליגזז — \u0003לא\u0004 מטמא! ודוחים: לא, אפשר לומר כי \u0003הכי קאמר\u0004 \u0005[כך\u0006 רבה בר בר חנה אומר\u0005]:\u0006 \u0003גזז —\u0004 \u0003הרי זה גלגלים\u0004 בוודאי. אבל \u0003לא גזז\u0004 — עדיין \u0003מיבעי ליה\u0004 \u0005[מסופק לו\u0006\u0005].\u0006","ועוד בענין רקב המת \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003ר' ירמיה: רקב הבא מן העקב מהו,\u0004 מה דינו? וצדדי השאלה: \u0003כי גמרינן\u0004 \u0005[כאשר אנו למודים\u0006\u0005]\u0006 במסורת הרי זה דווקא \u0003רקב הבא מכוליה\u0004 \u0005[מכולו\u0006\u0005],\u0006 מכל גופו של ה\u0003מת, אבל\u0004 רקב \u0003דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 \u0003מן\u0004 ה\u0003עקב —\u0004 \u0003לא, או דלמא לא שנא\u0004 \u0005[או שמא אינו שונה\u0006\u0005]?\u0006","ומציעים פתרון לבעיה זו: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה\u0006\u0005]\u0006 \u0003ר' נתן בר' אושעיא: רקב הבא משני מתים —\u0004 \u0003טמא. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר כי רקב \u0003הבא מן העקב לא\u0004 מטמא, אם כן \u0003זיל הכא\u0004 \u0005[לך לכאן\u0006\u0005] —\u0006 \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003דרך עקב קאתי\u0004 \u0005[בא\u0006\u0005]\u0006 הרקב, \u0003והכא\u0004 \u0005[וכאן\u0006\u0005] —\u0006 \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003דרך עקב קאתי\u0004 \u0005[בא\u0006\u0005],\u0006 ומדוע נאמר שטמא בוודאות? אלא ודאי אף רקב העקב טמא.","ודוחים: \u0003אי דאירקיב כוליה\u0004 \u0005[אם שנרקב כל\u0006\u0005]\u0006 ה\u0003מת וקאתי\u0004 \u0005[ובא\u0006\u0005]\u0006 \u0003דרך עקב —\u0004 \u0003הכי נמי\u0004 \u0005[כך הוא גם כן\u0006\u0005]\u0006 שכולו מטמא, ורקב העקב אינו נחשב כתערובת דבר זר. \u0003אלא הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 מדובר \u0003כגון דאירקיב חד אבר וקאתי\u0004 \u0005[שנרקב אבר אחד ובא\u0006\u0005]\u0006 \u0003דרך עקב,\u0004 ובזה שואל ר' ירמיה: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 דינו? האם בכלל רקב שמטמא הוא, או לא? לשאלה זו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006\u0005]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003ר' ירמיה: עובר\u0004 מת \u0003במעי אשה\u0004 שמתה, האם \u0003הוי\u0004 \u0005[הוא\u0006\u0005]\u0006 נעשה \u0003גלגלים\u0004 לה, כשני מתים הקבורים יחד, \u0003או לא?\u0004 וצדדי השאלה: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 \u0003עובר ירך אמו —\u0004 \u0003הלכך\u0004 (לכן) כ\u0003גופה הוא, ולא הוי\u0004 \u0005[נהיה\u0006\u0005]\u0006 \u0003גלגלין, או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003כיון\u0004 ש\u0003סופו לצאת,\u0004 שהרי העובר עשוי להיוולד, ולא יישאר בגופה — \u0003מיפרש פריש מינה\u0004 \u0005[מופרש\u0006 הוא ממנה\u0005]\u0006 ואינו נחשב כחלק ממנה, והריהו כמת אחר הקבור עמה. \u0003ואם תמצי לומר עובר\u0004 ש\u0003סופו לצאת מיפרש פריש מינה\u0004 \u0005[מופרש\u0006 הוא ממנה\u0005]\u0006 ואינו נחשב כחלק מגופה, עדיין יש לברר בענין"],["\u0003שכבת זרע\u0004 שהיתה \u0003במעי אשה\u0004 שמתה \u0003מהו\u0004 דינה לענין שתיעשה גלגלין לגוף האשה? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים\u0006\u0005]\u0006 \u0003כיון\u0004 ש\u0003לא איתצר\u0004 \u0005[נוצר\u0006\u0005]\u0006 עדיין ממנה עובר — \u0003כי\u0004 \u0005[כמו\u0006\u0005]\u0006 \u0003גופה דמי\u0004 \u0005[נחשב\u0006\u0005]\u0006 הדבר, \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003כיון דמעלמא קאתי\u0004 \u0005[שמן העולם,\u0006 מן החוץ, הוא בא\u0005]\u0006 הריהו \u0003לא\u0004 נחשב כגופה?","ובאותו ענין \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רב פפא: פירשה\u0004 (הפרש, מזון שבמעיה) \u0003מהו\u0004 דינו? וצדדי השאלה: \u0003כיון דלא מקיימא בדלא אכלה\u0004 \u0005[שאינה מתקיימת בלא לאכול\u0006\u0005] —\u0006 \u0003חיותא\u0004 \u0005[חייה\u0006\u0005]\u0006 \u0003הוא,\u0004 ולכן המזון שבמעיה נחשב כחלק ממנה, ואינו נעשה לה גלגלין, \u0003או דלמא הא נמי מעלמא אתי\u0004 \u0005[שמא זה גם כן מן העולם,\u0006 מן החוץ, הוא בא\u0005]\u0006 ולכן אינו נחשב כגופה? ובאותו ענין \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו\u0006\u0005]\u0006 של \u0003רב איקא: עורו\u0004 של המת \u0003מהו\u0004 דינו? וכן \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רב הונא בר מנוח: כיחו וניעו\u0004 (רוקו הבא מחמת שיעול) של המת \u0003מהו?\u0004","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב שמואל בר אחא לרב פפא: ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר כי \u0003כל הני דקאמר הוי\u0004 \u0005[אלה שאמר הם\u0006 נחשבים\u0005]\u0006 \u0003גלגלין, רקב\u0004 ש\u0003מטמא היכי משכחת לה\u0004 \u0005[איך\u0006 אתה יכול למצוא אותה\u0005],\u0006 שהרי תמיד חלק מן הרקב הוא מכל אותם הדברים! ומשיבים: כגון \u0003דאשקייה\u0004 \u0005[שהשקה אותו\u0006\u0005]\u0006 לפני מותו ב\u0003מי דקלים\u0004 שמשלשלים ביותר \u0003וסכיא נשא\u0004 \u0005[וסך\u0006 את שערו בסם המשיר שיער\u0005]\u0006 \u0003ושלקו\u0004 \u0005[ובישלו\u0006\u0005]\u0006 \u0003במי טבריא\u0004 החמים עד שעורו נקלף, שאז נפרדים ממנו כל הדברים שאינם חלק מגופו.","\u0003אמר אביי: נקטינן\u0004 \u0005[מוחזק לנו,\u0006 בידינו\u0005]:\u0006 \u0003מת שטחנו —\u0004 \u0003אין לו רקב. איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 אם \u0003טחנו\u0004 לאחר מותו \u0003וחזר והרקיב\u0004 לאחר זמן, \u0003מהו?\u0004 וצדדי השאלה: \u0003מידי הוא טעמא אלא דאיכא\u0004 \u0005[כלום\u0006 אין הטעם אלא משום שיש\u0005]\u0006 שם \u0003בשר וגידים ועצמות —\u0004 \u0003והאיכא\u0004 \u0005[והרי יש\u0006\u0005]\u0006 כאן כל אלה. \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003כברייתו בעינן\u0004 \u0005[צריכים אנו\u0006\u0005]\u0006 שיהא לפני שנרקב, \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005]?\u0006 לשאלה זו, כמו לשאלות הקודמות לא היתה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006\u0005]\u0006 במקומה.","\u0003תני\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003עולא בר חנינא: מת שחסר\u0004 בו משהו — \u0003אין לו\u0004 דין \u0003רקב\u0004 שמטמא במלוא תרווד, \u0003ולא\u0004 דין \u0003תפוסה,\u0004 כלומר, שאם מעבירים מת שחסר מהמקום בו הוא נמצא, אין מחשבים את האדמה שמסביבו כחלק ממנו, ואין מעבירים אותה עם גופתו. \u0003ו\u0004כן אין לו \u0003לא\u0004 דין \u0003שכונת קברות\u0004 שכאשר מוצאים במקום מסויים שלושה מתים בקירבת מקום זה לזה ואחד מהם מת חסר כזה — אין מחפשים מתים סמוכים, ואין חוששים שמא היתה שם שכונת קברות, כפי שהדין כאשר מוצאים שלושה מתים שלמים, אלא דינם של הנמצאים כמתים בודדים.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 על כך: אמרנו במשנה, בדין של כזית בשר שפרש מאבר מן החי, בשאלה האם הוא מטמא כבשר הפורש מאבר מן המת: \u0003לא, אם אמרת במת שיש לו\u0004 חומרה גדולה יותר לענין טומאה, ש\u0003רוב\u0004 בנין או מנין עצמותיו, \u0003ורובע\u0004 הקב מעצמותיו. \u0003או\u0004 אף \u0003מלא תרווד רקב\u0004 מטמאים, \u0003תאמר בחי שאין לו לא רוב ולא רובע ולא מלא תרווד רקב.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006\u0005]\u0006 מדובר באותה משנה העוסקת באבר מן החי — במקרה \u0003דארקיב חד אבר\u0004 \u0005[שנרקב אבר אחד\u0006\u0005]\u0006 מן החי, \u0003דכוותיה\u0004 \u0003גבי\u0004 \u0005[שכיוצא בו אצל\u0006\u0005]\u0006 \u0003מת\u0004 אמרה אותה משנה כי \u0003אפילו חד אבר איכא\u0004 \u0005[באבר אחד יש\u0006\u0005]\u0006 \u0003רקב,\u0004 ומתוך כך נלמד שלא רק מת שלם יש לו רקב, אלא אף מת שחסר! ודוחים: \u0003מי קתני הא מת\u0004 \u0005[האם שנה\u0006 שם כי מת זה\u0005]\u0006 המקרה המיוחד בו דנה המשנה — אבר בודד, יש לו רקב? דיוק זה אנו אמרנו ואינו משמעות המשנה, אלא \u0003הא קא משמע לן\u0004 \u0005[דבר זה השמיע לנו\u0006\u0005]:\u0006 \u0003שום\u0004 (שם) \u0003מת,\u0004 דין המת בכללו — \u0003יש לו רקב, שום\u0004 (שם) \u0003חי,\u0004 דינו — \u0003אין לו רקב.\u0004","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רבא: הרקיב\u0004 אבר מן הגוף \u0003כשהוא חי, וחזר\u0004 אותו איש \u0003ומת, מהו?\u0004 האם נאמר \u0003כי גמירי\u0004 \u0005[כאשר למדנו\u0006 במסורת\u0005]\u0006 דין \u0003רקב\u0004 שמטמא, הרי זה \u0003דאירקיב\u0004 \u0005[כשנרקב\u0006\u0005]\u0006 \u0003כשהוא מת\u0004 ולא כשהרקיב בחייו, ונמצא שדינו כמת שחסר, ואין רקב שלו מטמא. \u0003או דלמא השתא מיהא הא מיית\u0004 \u0005[או שמא עכשיו על כל פנים הריהו מת\u0006\u0005]\u0006 וכל גופו רקוב עתה במותו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 מן המשנה שהבאנו לעיל: \u0003לא, אם אמרת במת שיש לו רוב, ורובע, ומלא תרווד רקב, תאמר בחי כו'\u0004 שאין בו כל אלה, ובכללם דין רקב.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 \u0003משום\u0004 שהוא עדיין \u0003חי, הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אם היה \u0003מת —\u0004 \u0003יש לו רקב\u0004 ואפילו נרקב בחייו! ודוחים: \u0003מי קתני הא מת\u0004 \u0005[האם שנה\u0006 שם כי מת זה\u0005]\u0006 במקרה בו דנה המשנה — באבר מן החי, יש לו רקב? אין לדייק כך, אלא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר זה השמיע לנו\u0005]\u0006 ש\u0003שום\u0004 (שם) \u0003מת,\u0004 דין המת בכללו \u0003יש לו רקב, שום\u0004 (שם) \u0003חי —\u0004 \u0003אין לו רקב.\u0004","אגב הדיון במת שחסר, שאין לו כל דיני מת, מביאים, \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רבא: נמלה שחסרה,\u0004 כגון שניטלה אחת מרגליה, \u0003מהו\u0004 לענין מלקות על אכילתה? כי כאשר אדם אוכל נמלה שלימה, גם אם אין בה שיעור אכילה של כזית חייב עליה משום אכילת שרץ, כיון שהיא בריה שלימה. וצדדי השאלה: \u0003שיעורא\u0004 \u0005[שיעור\u0006\u0005]\u0006 נמלה שלימה \u0003גמירין לה\u0004 \u0005[למדנו\u0006 במסורת\u0005]\u0006 שחייבים עליו — \u0003והא\u0004 \u0005[ו\u0006אילו זה\u0005]\u0006 \u0003חסר. או\u0004 שעל \u0003בריה\u0004 (יצור) \u0003גמירי לה\u0004 \u0005[למדנו\u0006 במסורת\u0005]\u0006 שחייבים — \u0003והאיכא\u0004 \u0005[וזה יש כאן\u0006\u0005]\u0006 שהחסרון שבה אינו מוציא אותה מכלל בריה."],["\u0003אמר רב יהודה מדיסקרתא: תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ממדרש הלכה זה: נאמר בטומאת שרצים \"כל הנוגע \u0003בהם\u0004 במותם יטמא\" (ויקרא יא, לא), \u0003יכול\u0004 שתהא הלכה זו דווקא \u0003בכולן,\u0004 כלומר, בשרצים שלמים — \u0003תלמוד לומר:\u0004 \"וכל אשר יפול עליו \u0003מהם\u0004 במותם יטמא\" (ויקרא יא, לב) משמע שכל חלק מהם מטמא. \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 אתה מדייק \u0003\"מהם\", יכול\u0004 אף \u0003מקצתן —\u0004 \u0003תלמוד לומר: \"בהם\",\u0004 שמשמעו: בהם כולם.","\u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003כיצד\u0004 ניישב את שני המקראות הלו? \u0003עד שיגע\u0004 אף \u0003במקצתן שהוא\u0004 שיש בו שיעור \u0003ככולן. ושיערו חכמים\u0004 שיעור זה \u0003בכעדשה,\u0004 ומדוע? \u0003שכן החומט\u0004 שנמנה בין השרצים הטמאים \u0003תחלת ברייתו בכעדשה.\u0004 עד כאן מדרש ההלכה. ולענייננו \u0003שמע מינה שיעורא גמירי לה\u0004 \u0005[למד מכאן\u0006 ששיעור אנו למדים\u0005],\u0006 בלי קשר למהותה של הברייה. ואם כן, נמלה שחסרה — אינה מטמאה עוד.","\u0003אמר רב שמעיה\u0004 ודחה: \u0003כי בעינן שיעורא דבדלא הויא כעדשה\u0004 \u0005[כאשר אנו צריכים שיעור שכאשר אינו כעדשה\u0006\u0005]\u0006 הוא \u0003לא מטמא,\u0004 הרי זה במקרה ש\u0003לא נפלה בה נשמה\u0004 בבריה זו, קודם שתגיע לשיעור זה של עדשה. \u0003אבל נפלה בה נשמה —\u0004 \u0003לא,\u0004 שבוודאי נחשב כדבר מטמא כשיש בריה כשיכולה לחיות אף שהיא חסירה. ואם כן עדיין \u0003תיבעי\u0004 \u0005[תצטרך\u0006\u0005]\u0006 \u0003לך,\u0004 כלומר, לא נפתרה השאלה לגבי נמלה שחסרה.","שנינו במשנה שנזיר מגלח על \u0003\"השדרה והגולגולת\". איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003שדרה וגולגולת תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 שוא\"ו החיבור באה לומר שמדובר בשתיהן יחד, \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 הכוונה: \u0003או שדרה או גולגולת,\u0004 שוא\"ו זו באה לחלק, במשמעות \"או\"? \u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא: \u0003שדרה שגירד\u0004 והוריד \u0003רוב עילעין\u0004 (צלעות) \u0003שבה\u0004 ועמוד השדרה נשאר קיים — \u0003טהורה. ו\u0004אם היתה \u0003בקבר, אפילו\u0004 היא \u0003משוברת או מפורקת —\u0004 \u0003טמאה, מפני הקבר\u0004 שמצרף את כל העצמות.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003משום\u0004 ש\u0003גירד, הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אם \u0003לא גירד —\u0004 \u0003טמא\u0004 בעצמו אף ללא גולגולת, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]:\u0006 \u0003או שדרה או גולגולת קתני\u0004 \u0005[שנה\u0006\u0005].\u0006 ודוחים: \u0003הא\u0004 \u0005[זה\u0006\u0005]\u0006 \u0003לא קתני\u0004 \u0005[שנה\u0006\u0005]\u0006 במפורש, שלא נאמר שאם לא גירד הריהי מטמאה לבדה, אלא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר זה השמיע לנו\u0005]:\u0006 \u0003דכי\u0004 \u0005[שכאשר\u0006\u0005]\u0006 \u0003גירד —\u0004 \u0003טהורה,\u0004 \u0003אידך\u0004 \u0005[\u0006הענין האחר\u0005]\u0006 לעצם טומאת השדרה לבדה, עדיין \u0003תיבעי\u0004 \u0005[תישאל\u0006\u0005]\u0006 \u0003לך.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לדבר ממה ששנינו בברייתא אחרת, ש\u0003ר' יהודה אומר: ששה דברים\u0004 היה \u0003ר' עקיבא מטמא וחכמים מטהרין, וחזר בו ר' עקיבא\u0004 מדבריו. \u0003ומעשה שהביאו קופה\u0004 (תיבה) \u0003מלאה עצמות לבית הכנסת של טרסיים\u0004 (נפחים), \u0003והניחוה באויר\u0004 במקום שאינו מקורה, שלא תטמא, \u0003ונכנס תודוס הרופא וכל הרופאים\u0004 \u0005[עמו\u0006\u0005],\u0006 \u0003ואמרו\u0004 לאחר שבדקו: \u0003אין כאן שדרה ממת אחד.\u0004","ונדייק מכאן: \u0003טעמא דליכא שדרה דמחדא\u0004 \u0005[הטעם,\u0006 דווקא משום שאין פה שדרה שמ אדם אחד\u0005]\u0006 אין כאן טומאה. ומכאן נלמד: \u0003האיכא\u0004 \u0005[הרי אם יש\u0006\u0005],\u0006 \u0003או שדרה או גולגולת דמחדא\u0004 \u0005[שמ\u0006 איש אחד\u0005] —\u0006 \u0003נזיר מגלח עליה, שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 ש\u0003או שדרה או גולגולת תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שנזיר מגלח עליהם. ודוחים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר\u0006\u0005]:\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 \u0003שדרה וגולגולת\u0004 ש\u0003ממת אחד ליכא\u0004 \u0005[אין כאן\u0006\u0005],\u0006 \u0003אלא אפילו או שדרה ממת אחד או גולגולת ממת אחד,\u0004 ששניהם יחד מטמאים, \u0003ליכא\u0004 \u0005[אין\u0006\u0005],\u0006 שהיו שם שברי עצמות של שדרות וגולגולות ממתים רבים.","ומציעים עוד \u0003תא שמע ממניינא\u0004 \u0005[בוא\u0006 ושמע ממניין\u0005]\u0006 הדברים בברייתא, ששנינו: \u0003ומה הן ששה דברים שר' עקיבא מטמא וחכמים מטהרין: על אבר מן המת שבא\u0004 (מצטרף) \u0003משני מתים, ועל אבר מן החי שבא\u0004 (מצטרף) \u0003משני בני אדם\u0004 חיים, \u0003ועל חצי קב עצמות שבא משני מתים, ועל רביעית דם הבא משנים, ועל עצם כשעורה\u0004 אפילו ממת אחד \u0003שנחלק לשנים, והשדרה והגולגולת\u0004 משני מתים."],["\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר כי \u0003או שדרה או גולגולת\u0004 ושתי הלכות נפרדות הן, הרי \u0003הני\u0004 \u0005[אלה\u0006\u0005]\u0006 \u0003שבעה הויין\u0004 \u0005[הן\u0006\u0005]\u0006 ולא שישה! ודוחים: ממנין זה אין להוכיח, \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006\u0005]\u0006 את המניין הזה, מנה אומנם שבעה דברים, אבל רק שישה מהם שייכים במלואם לכאן, ולכן אמר שישה. (לתירוצים שנתנו לקושיה זו נתנו \u0003סימן: יחיד\u0004 חולק עליו, \u0003שהוא, גילח\u0004 — שנזיר מגלח עליו, \u0003ואחד\u0004 — רביעית אחת) ומסבירים באופן אחד: באמת מונה ר' עקיבא שדרה לחוד וגולגולת לחוד, אבל למנין שישה נמנה רק","\u0003כל היכא דפליגי עליה\u0004 \u0005[מקום שחולקים עליו\u0006\u0005]\u0006 \u0003רבים, לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003עצם כשעורה,\u0004 ש\u0003יחיד הוא דפליג עליה\u0004 \u0005[שחולק עליו\u0006\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003עצם כשעורה שנחלק לשנים, ר' עקיבא מטמא ור' יוחנן בן נורי מטהר.\u0004 משמע שרק יחיד הוא שחלק עליו, ולא כל החכמים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 הסבר באופן אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006\u0005]\u0006 שישה, הרי שנה בהם \u0003אבר מן המת,\u0004 אבל \u0003אבר מן החי לא קתני\u0004 \u0005[שנה\u0006\u0005],\u0006 ולא מנה אותו ביניהם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 הסבר באופן זה: \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006\u0005]\u0006 שישה, מנה \u0003כל היכא\u0004 \u0005[מקום\u0006\u0005]\u0006 \u0003שנזיר מגלח על אהילו,\u0004 אם היה מאהיל עליהם, שמטמאים טומאת אוהל, \u0003לאפוקי\u0004 \u0005[להוציא\u0006\u0005]\u0006 \u0003עצם כשעורה\u0004 שהיא \u0003לא\u0004 מטמאה באוהל, שהרי אמרנו במשנה שבזה יש רק טומאת מגע ומשא.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 הסבר אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006\u0005]\u0006 שישה, מנה \u0003כל היכא דהדר ביה\u0004 \u0005[מקום שחזר בו\u0006\u0005]\u0006 ר' עקיבא, \u0003לאפוקי\u0004 \u0005[להוציא\u0006\u0005]\u0006 \u0003רביעית דם\u0004 ש\u0003לא הדר ביה\u0004 \u0005[חזר בו\u0006\u0005]\u0006 וכפי ש\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רבי לבר קפרא: לא תשנה רביעית דם בחזרה,\u0004 בין הדברים שחזר בו ר' עקיבא, \u0003שהרי למודו של ר' עקיבא בידו,\u0004 כלומר, כך היה רגיל ללמד תמיד.","\u0003ועוד,\u0004 שכן \u0003המקרא מסייעו,\u0004 שנאמר: \u0003\"ועל כל נפשת מת לא יבא\"\u0004 (ויקרא כא, יא) ושינוי הלשון \"נפשות\", ברבים, מסייע לדברי ר' עקיבא. וכיוצא בזה, \u0003ר' שמעון אומר: עד ימיו\u0004 (כל ימי חייו) \u0003היה\u0004 ר' עקיבא \u0003מטמא\u0004 ברביעית דם משני מתים, \u0003אם משמת חזר בו —\u0004 \u0003איני יודע. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הושחרו שיניו\u0004 של ר' שמעון \u0003מפני תעניותיו\u0004 שהירבה להתענות על שאמר דברים אלה בלשון מבודחת על ר' עקיבא.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לשאלה ביחס לשדרה וגולגולת ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003בית שמאי אומרים: רובע עצמות\u0004 שאמרו שמטמא באוהל — \u0003מן העצמים\u0004 מכמה עצמות שונות \u0003או משנים או משלשה\u0004 עצמות. \u0003ובית הלל אומרים: רובע\u0004 עצמות \u0003מן הגויה\u0004 דווקא, \u0003מרוב הבנין\u0004 (רוב גובהו של השלד), \u0003או מרוב המנין\u0004 של רמ\"ח עצמות שבו. \u0003אמר ר' יהושע: יכולני\u0004 (יכול אני) \u0003לעשות דברי בית שמאי ודברי בית הלל כאחד.\u0004 כלומר, יכול אני לומר שאין ביניהם מחלוקת, והם מסכימים לשיטה אחת. כיצד?","\u0003שבית שמאי אומרים: משנים או משלשה\u0004 — כוונתו \u0003או משני שוקיים וירך אחד, או משני ירכיים ושוק אחד, הואיל ורוב גובהו של אדם\u0004 נמצא בהם \u0003מגובה,\u0004 והרי זה רוב בניין. \u0003ובית הלל אומרים: מן הגויה או מרוב בנין, או מרוב מנין —\u0004 \u0003הואיל וישנן במפרקי ידים ורגלים\u0004 שיש עצמות קטנות ורבות מאד. \u0003שמאי אומר: אפילו עצם מן השדרה או מן הגולגולת.\u0004 ואם כן, מלשונו המפורשת של שמאי פתרנו שמדובר על שדרה או גולגולת.","ודוחים: מכאן אין להוכיח הלכה כללית, שכן \u0003שאני\u0004 \u0005[שונה\u0006\u0005]\u0006 \u0003שמאי\u0004 ש\u0003מחמיר\u0004 בכלל, ושמא אין חכמים סבורים כן. ואומרים: \u0003ליפשוט מינה\u0004 \u0005[ונפתור ממנה\u0006\u0005]\u0006 מברייתא זו להיפך: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003בית שמאי\u0004 ש\u0003מחמיר\u0004 הוא שאומר שדרה או גולגולת, \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 לשיטת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 \u0003עד דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003שדרה וגולגולת\u0004 יחד! ואף ראיה זו דוחים: \u0003לא, עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו\u0006\u0005]\u0006 על \u0003שמאי אלא בעצם אחד דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 \u0003מן השדרה ומן הגולגולת, אבל היכא דאיתיה בעיניה\u0004 \u0005[במקום שישנו בעינו\u0006\u0005]\u0006 והוא שלם, \u0003אפילו חדא מינהון\u0004 \u0005[אחת מהן\u0006\u0005]\u0006 מן השדרה או מן הגולגולת יש לומר שמטמא.","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רמי בר חמא: רובע עצמות מן שדרה וגולגולת מאי\u0004 \u0005[מה\u0006\u0005]\u0006 דינם? האם נזיר מגלח עליהם? וצדדי הבעיה: \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006\u0005]\u0006 במשנתנו שמגלח על \u0003חצי קב עצמות —\u0004 \u0003היכא דאיכא\u0004 \u0005[מקום שהוא\u0006\u0005]\u0006 בא ומצטרף \u0003משאר אבריו, אבל מן שדרה וגולגולת דחמירי\u0004 \u0005[ש\u0006הם חמורים\u0005]\u0006 שהרי הם מטמאים לעצמם — \u0003אפילו רובע עצמות\u0004 גם כן מטמא. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה\u0006\u0005]?\u0006","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לבעיה זו, ממה ששנינו במשנתנו: \u0003השדרה והגולגולת. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר \u0003רובע עצמות דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 \u0003מן שדרה וגולגולת חמיר\u0004 \u0005[חמור\u0006\u0005]\u0006 יותר ומטמא ברובע — \u0003ליתני\u0004 \u0005[שישנה\u0006\u0005]\u0006 בלשון שיש בה חידוש יותר: \u0003על רובע עצמות הבא מן השדרה\u0004 ומן הגולגולת!"],["\u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003רבא\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר: לא נצרכה אלא לשדרה וגולגולת\u0004 (שלמים) אף \u0003שאין בהן רובע עצמות\u0004 ומכאן שלדבריו רובע עצמות מן השדרה מטמא! ומשיבים: \u0003בתר\u0004 \u0005[אחר\u0006\u0005]\u0006 ש\u0003שמעה\u0004 הבין את הדבר \u0003מ\u0004דברי \u0003ר' עקיבא\u0004 שחלק בברייתא לגבי שדרה וגולגולת שבאו משני מתים, ולא הזכיר רובע הקב, שינה את דעתו בענין זה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לשאלה ממה ששנינו ש\u0003שמאי אומר: עצם אחד מן שדרה או מן גולגולת\u0004 מטמא, ואף חכמים שחולקים עליו, מן הסתם אינם חולקים עליו באופן קיצוני כל כך, ואף הם יודו לו שרובע הקב מן השדרה מטמא, ונזיר מגלח עליו! ודוחים: \u0003שאני\u0004 \u0005[שונה\u0006\u0005]\u0006 \u0003שמאי\u0004 ש\u0003מחמיר טפי\u0004 \u0005[ביותר\u0006\u0005]\u0006 ואין ללמוד ממנו לגבי שיטת חכמים.","ואומרים: אם כן, תיתכן מחלוקת קיצונית בין שמאי לחכמים, \u0003ליפשוט מינה\u0004 \u0005[נפתור ממנה\u0006\u0005]\u0006 את הבעיה לצד שני: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום שהיא שיטת \u0003שמאי,\u0004 שהוא \u0003מחמיר\u0004 ביותר, \u0003הא לרבנן\u0004 \u0005[הרי ל\u0006שיטת חכמים\u0005]\u0006 \u0003עד דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003חצי קב עצמות\u0004 משדרה וגולגולת אינו מטמא ואין הנזיר מגלח!","ואף טענה זו דוחים: \u0003דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו\u0006\u0005]\u0006 על \u0003שמאי אלא בעצם אחד\u0004 משדרה וגולגולת שאינו מטמא, \u0003אבל ברובע עצמות\u0004 אפשר לומר כי \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים\u0006\u0005]\u0006 שמטמא, ונזיר אף מגלח עליו.","\u0003אמר ר' אליעזר: זקנים הראשונים, מקצתן היו אומרים: חצי קב עצמות, וחצי לוג דם לכל\u0004 הוא מטמא, שהיא טומאה מן התורה ומטמאה באוהל לכל ענין. \u0003רובע עצמות, ורביעית\u0004 לוג \u0003דם לא לכל,\u0004 כלומר, אינה מטמאה באוהל כלל, לשום ענין. \u0003ומקצתן היו אומרים: אף רובע עצמות ורביעית דם לכל.\u0004 זו מחלוקת שהיתה בדורות ראשונים.","\u0003בית דין שלאחריהם אמרו: חצי קב עצמות וחצי לוג דם —\u0004 \u0003לכל, רובע עצמות ורביעית דם\u0004 — מטמאים רק \u0003לתרומה וקדשים,\u0004 שהחמירו עליהם שמטמאים טומאת אוהל לפסול על ידם תרומה וקדשים. \u0003אבל לא לנזיר\u0004 שאינו מגלח ומביא קרבנות על כך, \u0003ועושה פסח\u0004 שמותר לעשותו גם אם נטמא בכך, שלא החמירו חכמים במקום שיש בו איסור כרת.","ושואלים: כיצד פוסקים הלכה באופן זה? \u0003מכדי\u0004 \u0005[הרי\u0006\u0005]\u0006 כלל בידינו ש\u0003אין הכרעת שלישית מכרעת,\u0004 שדעה נוספת שהיא רק ממוצעת בין שתי דעות חולקות — אינה נחשבת להכרעה ביניהן! \u0003אמר ר' יעקב בר אידי:\u0004 לא כפשרה נאמרה שיטה זו, אלא \u0003מפי שמועה\u0004 (מסורת) \u0003אמרו: מפי חגי זכריה ומלאכי,\u0004 אחרוני הנביאים. שאינה הכרעה חדשה בין שיטות הראשונים, אלא שיטה קדומה יותר בפני עצמה.","שנינו במשנה \u0003\"על אלו הנזיר מגלח\".\u0004 ומסבירים את דיוק הלשון: \u0003\"על אלו\" דרישא\u0004 \u0005[ש\u0006נאמר בראש המשנה\u0005]\u0006 בא \u0003למעוטי\u0004 \u0005[למעט\u0006\u0005]\u0006 \u0003עצם כשעורה,\u0004 ש\u0003על מגעו ועל משאו —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 מגלח, \u0003ועל אהילו\u0004 בטומאת אוהל — \u0003לא\u0004 מגלח. \u0003ו\"על אלו\" דסיפא\u0004 \u0005[שבסוף\u0006\u0005] —\u0006 \u0003למעוטי\u0004 \u0005[למעט\u0006\u0005]\u0006 \u0003אבן הסכוכית,\u0004 אבן שמסככת על מקום טומאת המת, שאף שיש בה טומאת אוהל במקרה של ספק — מכל מקום אין הנזיר מגלח עליה.","ממה ששנינו במשנה \u0003\"וחצי קב עצמות\"\u0004"],["\u0003חצי קב עצמות\u0004 — \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 ואולם \u0003רובע עצמות —\u0004 \u0003לא. היכי דמי\u0004 \u0005[כיצד בדיוק מדובר\u0006\u0005]?\u0006 \u0003אילימא דאית בהון\u0004 \u0005[אם תאמר שיש בהן\u0006\u0005]\u0006 \u0003עצמות כשעורה —\u0004 \u0003תיפוק ליה\u0004 \u0005[תצא לו\u0006\u0005]\u0006 שמטמא \u0003משום עצם כשעורה! אלא דאקמח אקמוחי\u0004 \u0005[שנעשו כקמח\u0006\u0005],\u0006 ובזה מטמא חצי קב עצמות באוהל, אף שלא נשארה בהן עצם כשעורה.","שנינו כי נזיר מגלח \u0003\"על אבר מן המת ועל אבר מן החי שיש עליהן בשר כראוי\".\u0004 ושואלים: ואם \u0003אין עליהן בשר כראוי, מאי\u0004 \u0005[מה\u0006\u0005]\u0006 הדין? \u0003ר' יוחנן אמר: אין הנזיר מגלח עליהן. ריש לקיש אמר: הנזיר מגלח עליהן.\u0004","ומסבירים את דעותיהם: \u0003ר' יוחנן אמר: אין הנזיר מגלח עליהן, דהא קתני ברישא\u0004 \u0005[שהרי שנה בתחילה\u0006\u0005]\u0006 במשנתנו, ברשימת הטומאות שהנזיר מגלח עליהן: \u0003על אבר מן המת ועל אבר מן החי\u0004 שיש עליהן בשר כראוי, ונדייק: \u0003שיש עליהן כזית בשר —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 מגלח עליהם, \u0003אבל אין עליהם\u0004 בשר — \u0003לא\u0004 מגלח עליהם.","\u0003ור' שמעון בן לקיש אומר: מגלח.\u0004 ודיוקו: \u0003מ\u0004תוך זה ש\u0003לא קתני בסיפא\u0004 \u0005[שנה בסוף\u0006 המשנה\u0005],\u0006 להלן, ברשימת הטומאות שאין הנזיר מגלח עליהם, גם אבר שאין עליו בשר כראוי, מכאן שמגלח עליו.","\u0003ור' יוחנן אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך:\u0004 אין להוכיח ממה שלא הזכיר להלן שאינו מגלח, כי \u0003כל היכא דמשמע מכללא לא קתני בסיפא\u0004 \u0005[כל דבר\u0006 שאפשר לשמוע אותו מכלל מה שנאמר בתחילה אינו שונה אותו התנא בסוף\u0005].\u0006","ומקשים על הסבר זה של ר' יוחנן: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003חצי קב עצמות\u0004 שנאמר במשנתנו, ש\u0003משמע\u0004 מכלל הדברים: \u0003חצי קב עצמות —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 מגלחים עליו, \u0003רובע עצמות —\u0004 \u0003לא\u0004 מגלחים עליו, \u0003וקתני בסיפא\u0004 \u0005[ו\u0006מכל מקום שנה בסוף\u0005]\u0006 שאין מגלח על \u0003רובע עצמות.\u0004 ומכאן ראיה שאין סופה של המשנה סומך על תחילתה של המשנה, ומונה את הדברים שאין מגלחים!","ודוחים: \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 \u0003אי לאו\u0004 \u0005[אם לא\u0006\u0005]\u0006 היה שונה \u0003רובע עצמות, הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003אפילו על מגעו ועל משאו לא\u0004 יגלח, \u0003להכי איצטריך למיתני\u0004 \u0005[לכן היה צריך לשנות\u0006\u0005]\u0006 \u0003רובע עצמות,\u0004 לומר ש\u0003על אהילן\u0004 (טומאת אוהל שלהן) בלבד \u0003הוא\u0004 ש\u0003אין הנזיר מגלח.\u0004","ומקשים עוד: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003חצי לוג דם,\u0004 ששנינו במשנתנו שנזיר מגלח עליו, \u0003דשמעת מינה\u0004 \u0005[שאתה למד מכאן\u0006\u0005]\u0006 \u0003חצי לוג דם —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 מגלח עליו, \u0003רביעית דם לא\u0004 מגלח עליו, \u0003ו\u0004בכל זאת \u0003קתני בסיפא\u0004 \u0005[שנה בסוף\u0006 המשנה\u0005]\u0006 \u0003רביעית דם\u0004 שאין מגלח עליה! ומשיבים: \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 נצרך הדבר להיאמר במפורש, כדי \u0003לאפוקי\u0004 \u0005[להוציא\u0006\u0005]\u0006 \u0003מ\u0004דברי \u0003ר' עקיבא.\u0004 ש\u0003אמר ר' עקיבא: רביעית דם הבא משני מתים מטמא באהל,\u0004 ובמשנה נאמר רביעית סתם, כלומר, רק מאדם אחד.","ומבררים את מחלוקתם זו של ר' יוחנן וריש לקיש: \u0003האי\u0004 \u0005[אותו\u0006\u0005]\u0006 \u0003אבר מן המת\u0004 שאין עליו בשר, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר\u0006\u0005]?\u0006 \u0003אי דאית ביה\u0004 \u0005[אם שיש בו\u0006\u0005]\u0006 \u0003עצם כשעורה —\u0004 \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003ר' יוחנן\u0004 הסבור שאינו מגלח עליו? שהרי אף ללא הבשר מטמא משום העצם! \u0003ואי דלית ביה\u0004 \u0005[ואם שאין בו\u0006\u0005]\u0006 \u0003עצם כשעורה, מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003ריש לקיש\u0004 הסבור שמגלח עליו? ומסבירים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך ריש לקיש: לעולם\u0004 מדובר \u0003דלית ביה\u0004 \u0005[שאין בו\u0006\u0005]\u0006 \u0003עצם כשעורה, ואפילו הכי\u0004 \u0005[כך\u0006\u0005]\u0006 \u0003רחמנא רביה\u0004 \u0005[התורה ריבתה אותו\u0006\u0005]\u0006 שיטמא.","\u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 על הנאמר \u0003\"וכל אשר יגע על פני השדה בחלל חרב או במת\u0004 או בעצם אדם או בקבר יטמא שבעת ימים\u0003\"\u0004 (במדבר יט, טז), דרשו: \u0003\"על פני השדה\" —\u0004 \u0003זה\u0004 בא ללמד דינו של \u0003המאהיל על פני המת\u0004 גם כאשר אינו נוגע בו. \u0003\"בחלל\"\u0004 שמתפרש במי שנחתך (\"נחלל\") ממנו דבר — \u0003זה אבר מן החי\u0004 שנחתך \u0003ויש לו\u0004 בשר כדי \u0003להעלות ארוכה\u0004 (להתרפא).","ועוד למדים מן הצירוף \"בחלל חרב\" — לומר כי \u0003\"חרב\" הרי זו כחלל,\u0004 ללמד שכלי, כחרב, שנטמא במת — נעשה טמא טומאה חמורה כמת עצמו. \u0003\"או במת\" —\u0004 \u0003זה אבר הנחלל מן המת\u0004 ויש בו בשר כדי להעלות ארוכה בחי. \u0003\"או בעצם אדם\" —\u0004 \u0003זה רובע עצמות. \"או בקבר\" —\u0004 \u0003זה קבר סתום\u0004 שאין מקום פנוי (כדי טפח) בין המת והכיסוי שעליו, שאף הוא מטמא."],["\u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]:\u0006 \u0003טומאה\u0004 בקבר סתום — \u0003בוקעת ועולה, בוקעת ויורדת,\u0004 ומטמא הקבר כמת עצמו. \u0003ואילו גבי נגיעה\u0004 באלה, \u0003אמר רב יהודה, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"וכל הנגע בעצם או בחלל\"\u0004 (במדבר יט, יח) \u0003\"בעצם\" —\u0004 \u0003זה עצם כשעורה, \"או בחלל\" —\u0004 \u0003זה אבר הנחלל\u0004 (הנחתך) \u0003מן החי ואין בו\u0004 בשר כדי \u0003להעלות ארוכה\u0004 (שאינו יכול להתרפא),","\u0003\"או במת\" —\u0004 \u0003זה אבר הנחלל מן המת\u0004 ואין בו בשר כדי להעלות ארוכה בחי, \u0003\"או בקבר\" —\u0004 \u0003אמר ריש לקיש: זה קבר שלפני הדיבור,\u0004 מן הזמן לפני שניתנה מצוה זו לישראל. ואלה יש בהם טומאת מגע אבל לא טומאת אוהל.","ונברר: \u0003האי\u0004 \u0005[זה\u0006\u0005]\u0006 \u0003אבר מן המת\u0004 שהזכרנו שמטמא במגע, \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק\u0006\u0005]?\u0006 \u0003אי דאית ביה\u0004 \u0005[אם שיש בו\u0006\u0005]\u0006 \u0003עצם כשעורה —\u0004 \u0003היינו\u0004 \u0005[הרי הוא\u0006\u0005]\u0006 בכלל \u0003הנוגע בעצם\u0004 שנלמד כבר שמטמא במגע! \u0003אלא\u0004 צריך לומר \u0003דלית ביה\u0004 \u0005[שאין בו\u0006\u0005]\u0006 \u0003עצם כשעורה, ואפילו הכי\u0004 \u0005[כך\u0006\u0005]\u0006 \u0003רחמנא רביה\u0004 \u0005[התורה ריבתה אותו\u0006\u0005]\u0006 לטומאה אף אם אין עליו בשר כראוי, ואם כן אף עליו נזיר מגלח, וכדברי ריש לקיש!","ומעירים: בתשובה לראיה זו של ריש לקיש \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך ר' יוחנן: לעולם\u0004 תפרש \u0003דאית ביה\u0004 \u0005[שיש בו\u0006\u0005]\u0006 עצם כשעורה. \u0003ואם אינו ענין למגעו\u0004 שהרי נאמר במפורש \"הנוגע בעצם\" — \u0003תנהו ענין למשאו,\u0004 שגם הנושא אותו נטמא.","שנינו במשנה כי כל נזיר הנטמא באחת מן הטומאות המנויות בה \u0003מזה בשלישי ובשביעי וסותר\u0004 את הקודמים, ואינו מתחיל למנות אלא עד שיטהר, ומביא את קרבנותיו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003הא דקתני\u0004 \u0005[זה ששנה\u0006\u0005]\u0006 \"ואינו מתחיל למנות \u0003עד שיטהר\"\u0004 מה עניינו? האם מדובר במי ש\u0003ב\u0004יום ה\u0003שביעי\u0004 לטהרתו הוא \u0003קאי\u0004 \u0005[עומד\u0006\u0005],\u0006 והכוונה \"שיטהר\" — \u0003עד דעביד\u0004 \u0005[ש\u0006הוא עושה\u0005]\u0006 \u0003הערב שמש,\u0004 \u0003ומני\u0004 \u0005[ו\u0006כשיטת מי היא\u0005] —\u0006 כשיטת \u0003ר' אליעזר היא\u0004 שמתחיל למנות מתחילת יום שמיני, ואף לפני הבאת קרבנותיו. \u0003או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 המדובר במי ש\u0003ב\u0004יום ה\u0003שמיני קאי\u0004 \u0005[עומד\u0006\u0005],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"עד שיטהר\" —\u0004 \u0003עד שיביא קרבנותיו. ומני\u0004 \u0005[ו\u0006שיטת מי היא\u0005] —\u0006 \u0003רבנן\u0004 \u0005[\u0006שיטת חכמים\u0005]\u0006 \u0003היא\u0004 שאינו מתחיל למנות נזירותו מחדש עד שיביא קרבן לטומאת נזירותו?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לבעיה זו \u0003מדקתני סיפא\u0004 \u0005[ממה ששנה בסוף\u0006\u0005]\u0006 במשנה הבאה, המדברת במי שאינו צריך להביא קרבן \u0003\"מתחיל ומונה מיד\"\u0004 לאחר שסיים שבעת ימי טהרתו, מכאן נדייק: \u0003הא רישא מאי\u0004 \u0005[הרי בתחילה מה\u0006 הכוונה\u0005]\u0006 \u0003\"עד שיטהר\"\u0004 כוונתו \u0003עד שיביא קרבנותיו, ומני\u0004 \u0005[ו\u0006שיטת מי\u0005]\u0006 — שיטת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 \u0003היא דאמרי\u0004 \u0005[שאומרים\u0006\u0005]:\u0006 \u0003נזירות\u0004 של \u0003טהרה עד\u0004 היום ה\u0003שמיני לא חיילא\u0004 \u0005[חלה\u0006\u0005].\u0006","במשנה הקודמת שנינו על אלו טומאות הנזיר מגלח. ובמשנה זו מוסיפים: \u0003אבל הסככות,\u0004 עצים שידוע שענפיהם סוככים על המת, ולא ידוע היכן בדיוק נמצא המת ותחת איזה ענף, ועבר שם הנזיר. \u0003ו\u0004כן \u0003הפרעות,\u0004 אבנים היוצאות מן הגדר שיש תחתיהן טומאת מת ולא ידוע היכן הטומאה, \u0003ובית הפרס,\u0004 מקום שהיה בו קבר ונחרש, שיש בו מעתה סביב לאותו קבר ספק טומאת מת, שמא יש שם מעצמות המת,","\u0003וארץ העמים\u0004 שגזרו חכמים עליה טומאה ויצא אליה הנזיר תוך ימי נזירותו, \u0003והגולל\u0004 שסוגרים בו את הקבר, \u0003ו\u0004כן \u0003הדופק\u0004 שעליו נשען הגולל, \u0003ורביעית דם\u0004 מן המת, \u0003ואהל, ורובע עצמות\u0004 של מת, \u0003וכלים הנוגעים במת, ו\u0004כן אם הנזיר נמצא \u0003בימי ספרו\u0004 (ספירתו) שהם שבעת הימים שהוא סופר לאחר שנרפא מצרעתו, להיטהר מטומאת צרעת, \u0003ובימי גמרו\u0004 בזמן שהוא מצורע מוחלט, \u0003על אלו\u0004 אף על פי שהוא טמא בכולם, מכל מקום \u0003אין הנזיר מגלח. ו\u0004בכל אלה מהם שטומאתם כטומאת המת","\u0003מזה בשלישי ובשביעי,\u0004 מי חטאת לטהרו,"],["\u0003ואינו סותר את\u0004 ימי הנזירות \u0003הקודמים,\u0004 שעולים לו למנין הנזירות, \u0003ומתחיל ומונה מיד\u0004 לאחר שנטהר מטומאתו, להשלים את מנין ימי נזירותו, \u0003וקרבן\u0004 טומאה \u0003אין לו\u0004 על כל אלה הטומאות. \u0003באמת אמרו,\u0004 מסורת עתיקה היתה: \u0003ימי\u0004 טומאת \u0003הזב והזבה וימי הסגרו של מצורע\u0004 כשהיה מצורע מוסגר בלבד, לפני שנתברר אם הוא מצורע מוחלט, \u0003הרי אלו עולין\u0004 (נחשבים) \u0003לו\u0004 למנין ימי הנזירות.","הוזכרו במשנתנו הסככות והפרעות. ומסבירים מהם דברים אלה ממה ששנינו במשנה במקום אחר: \u0003ואלו הן הסככות\u0004 — זה \u0003אילן המיסך על הארץ. ופרעות\u0004 — אלו אבנים \u0003היוצאות מן הגדר.\u0004","עוד שנינו במשנה: \u0003ו\u0004אף ש\u0003ארץ העמים\u0004 מטמאה — אין הנזיר מגלח על טומאה זו. ומבררים מהו עניינה של טומאה זו, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ארץ העמים, משום אוירא\u0004 \u0005[האויר,\u0006 החלל שלה\u0005]\u0006 \u0003גזרו עליה\u0004 חכמים טומאה, כלומר, על עצם השהות בה. \u0003או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003משום גושא\u0004 \u0005[גושה,\u0006 אדמתה\u0005]\u0006 \u0003גזרו עליה\u0004 כאילו היה שם מת, שרק אם נוגע בה או מאהיל עליה הריהו טמא?","ומציעים \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לשאלה זו ממה ששנינו במשנתנו, המונה גם את הנכנס בארץ העמים: \u0003ומזה בשלישי ובשביעי. ואי אמרת\u0004 \u0005[ואם אומר אתה\u0006\u0005]\u0006 \u0003משום אוירא\u0004 \u0005[החלל\u0006\u0005]\u0006 עצם השהות בה גזרו, \u0003הזאה למה לי?\u0004 הרי לא נגע בטומאה, ולא האהיל עליה!","\u0003אלא לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 \u0003משום גושא\u0004 \u0005[הגוש,\u0006 האדמה עצמה\u0005]?\u0006 ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר\u0006\u0005]\u0006 \u0003לך משום אוירא\u0004 \u0005[החלל\u0006\u0005],\u0006 \u0003וכי קתני\u0004 \u0005[וכאשר שנה\u0006\u0005]\u0006 שמזים עליו — הכוונה היא \u0003אשארא\u0004 \u0005[על,\u0006 לגבי, שאר\u0005]\u0006 העניינים הנזכרים במשנה, כגון הגולל והדופק ורביעית דם.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006\u0005]\u0006 לפרש, \u0003מדקתני\u0004 \u0005[ממה ששנה\u0006\u0005]\u0006 במשנה גם: \u0003וכלים, הנוגעים במת.\u0004 וכי הנוגעים ב\u0003הני\u0004 \u0005[אלה\u0006\u0005]\u0006 ה\u0003כלים בני הזאה אינון\u0004 \u0005[הם\u0006\u0005]?\u0006 האם הנוגע בכלי הטמא טומאת מת צריך הזאה? והרי אינו טמא אלא טומאת ערב בלבד! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 \u0003אשארא\u0004 \u0005[על השאר\u0006\u0005]\u0006 מדובר, שאין ההלכה \"ומזה בשלישי ובשביעי\" מתייחסת לכל הדברים שנמנו במשנה, אלא לחלקם בלבד."],["\u0003לימא כתנאי\u0004 \u0005[\u0006האם נאמר שמחלוקת תנאים\u0005]\u0006 היא בענין זה, שכן שנינו: \u0003הנכנס לארץ העמים\u0004 באופן שהוא נמצא \u0003ב\u0004תוך \u0003שידה תיבה ומגדל\u0004 שאינם מקבלים טומאה, \u0003רבי מטמא\u0004 אותו, \u0003ור' יוסי בר' יהודה מטהר. מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 בכך נחלקו: \u0003רבי\u0004 שמטמא אותו \u0003סבר משום אוירא\u0004 \u0005[האויר\u0006\u0005]\u0006 עצם השהות בה גזרו טומאה, והרי אדם זה נמצא בחלל ארץ העמים, \u0003ו\u0004אילו \u0003ר' יוסי בר' יהודה סבר\u0004 \u0005[סבור\u0006\u0005]\u0006 \u0003משום גושא\u0004 \u0005[הגוש,\u0006 האדמה\u0005]\u0006 גזרו ולא משום עצם השהות בה, ולכן אינו טמא, משום שהתיבה חוצצת בינו לבין האדמה שלא ייחשב גם כמאהיל עליה?","ודוחים: \u0003לא\u0004 זה הסבר מחלוקתם, כי אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל\u0006\u0005]\u0006 \u0003משום גושא\u0004 \u0005[הגוש,\u0006 האדמה\u0005]\u0006 גזרו, והמחלוקת ביניהם היא דווקא משום שנכנס בשידה תיבה ומגדל, וטעמם: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוסי בר' יהודה, סבור\u0005]\u0006 ש\u0003אהל זרוק,\u0004 דבר המאהיל על הטומאה באופן שאיננו קבוע במקום אחד ועובר על פניה — \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003אהל\u0004 ולכן הנכנס בתיבה לארץ העמים — האוהל חוצץ בינו לבין הטומאה, ואין האדם היושב בתיבה נטמא. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, סבור\u0005]\u0006 אוהל זרוק \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003אהל,\u0004 וכאילו לא היתה חציצה כלל בינו ובין הטומאה, והרי הוא כמאהיל על אדמת ארץ העמים ונטמא על ידי כך.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: תיבה שהיא מלאה כלים וזרקה על\u0004 (מעל) \u0003פני המת באהל,\u0004 כלומר, באופן שהאהילה עליו — \u0003טמאה\u0004 ונטמא כל מה שבתוכה, \u0003ואם היתה מונחת\u0004 והאהילה מעל המת — \u0003טהורה\u0004 וחוצצת בפני הטומאה. משמע שאוהל זרוק אינו נחשב לאוהל לדעת ר' יוסי בר' יהודה, והרי זה בניגוד לדברים שאמרנו קודם.","ואם כן אי אפשר לפרש את מחלוקת רבי ור' יוסי בר' יהודה כפי שפירשנו עתה, \u0003אלא\u0004 צריך לומר: \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל\u0006\u0005]\u0006 מטמאה ארץ העמים \u0003משום אוירא\u0004 \u0005[חללה\u0006\u0005],\u0006 \u0003ו\u0004בזה נחלקו: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוסי בר' יהודה, סבור\u0005]:\u0006 \u0003כיון\u0004 ש\u0003לא שכיחא\u0004 \u0005[מצוי\u0006\u0005]\u0006 שייכנס אדם בדרך זו — \u0003לא גזרו ביה רבנן\u0004 \u0005[בו\u0006 באופן כזה חכמים\u0005],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, סבור\u0005]:\u0006 \u0003אף על גב דלא שכיחא\u0004 \u0005[אף על פי שאין\u0006 זה מצוי\u0005] —\u0006 \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים\u0006\u0005].\u0006","\u0003והתניא\u0004 \u0005[ו\u0006אכן כן שנינו בברייתא\u0005]\u0006 לדרך זו, וכשיטת ר' יוסי בר' יהודה: \u0003הנכנס לארץ העמים בשידה תיבה ומגדל —\u0004 \u0003טהור,\u0004 אם נכנס \u0003בקרון ובספינה ובאיסקריא\u0004 (אניה גדולה) — \u0003טמא\u0004 כיון שהוא דבר מצוי. הרי שהגזירה תלויה בשכיחות הדבר, שבשידה תיבה ומגדל אין רגילים להיכנס ולכן לא גזרו בהם, מה שאין כן בקרון ובספינה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 הסבר נוסף במחלוקת רבי ור' יוסי בר' יהודה: שלדעת כולם גזרו על ארץ העמים משום גושה, ואוהל זרוק נחשב אוהל, ולכן היה צריך להיות טהור לכל הדעות, ואולם \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 בעניין אחר נחלקו, בחשש \u0003שמא יוציא\u0004 החוצה את \u0003ראשו ורובו\u0004 מן השידה, התיבה, והמגדל \u0003לשם\u0004 לארץ העמים \u0003פליגי\u0004 \u0005[נחלקו\u0006\u0005].\u0006","\u0003והתניא\u0004 \u0005[ו\u0006אכן כן שנינו בברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: הנכנס לארץ העמים בשידה תיבה ומגדל —\u0004 \u0003טהור, עד שיוציא לשם ראשו או רובו.\u0004 ורבי שמטמא — סבור שיש לחשוש שמא יוציא ראשו, וייטמא מפני ספק זה.","שנינו במשנה שנזיר שנטמא בטומאות שאין נזירותו נסתרת בהן ובכללן ימי צרעתו, \u0003מתחיל ומונה\u0004 מיום שנטהר ואין ימי טומאתו עולים לו למנין ימי נזירותו. \u0003אמר רב חסדא: לא שנו\u0004 דבר זה לענין מי שהיה מצורע \u0003אלא\u0004 דווקא \u0003בנזירות מועטת\u0004 של שלושים יום, לפי שצריך לגלח את שיער ראשו להיטהר מצרעתו, ולכן מונה שלושים יום נוספים לגידול שיער הראוי לתגלחת נזיר. \u0003אבל בנזירות מרובה\u0004 שאחר שגילח לצרעתו נותרו לו עוד שלושים יום ויותר של נזירות, באופן שיוכל שערו שוב לצמוח — \u0003מיסלק נמי סלקין ליה\u0004 \u0005[לעלות, גם כן עולים לו\u0006\u0005]\u0006 הימים הללו ואינו צריך להשלים כלל את ימי צרעתו.","\u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רב שרביא,\u0004 והרי שנינו: \u0003מתחיל ומונה מיד, ואין ומבטל בהן את הקודמין.\u0004 ונברר: \u0003במאי\u0004 \u0005[במה\u0006\u0005]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 כי מדובר \u0003בנזירות מועטת\u0004 — הלא \u0003קבעי\u0004 \u0005[צריך\u0006\u0005]\u0006 \u0003גידול שיער\u0004 של חודש לפחות, וזה לא היה כאן, שהרי גילח את שערו כשנטהר מצרעתו, ולפיכך הרי בפועל מבטל בכך את הימים הקודמים!"],["\u0003אלא לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 מדובר \u0003בנזירות מרובה,\u0004 \u0003וקתני\u0004 \u0005[ושנה\u0006\u0005]:\u0006 \u0003מתחיל ומונה מיד\u0004 שמעתה מתחיל להשלים ימי הנזירות, ואין ימי צרעתו עולים למנין זה! ומעירים: \u0003הוא,\u0004 רב שרביא, \u0003מותיב לה\u0004 \u0005[הקשה אותה\u0006\u0005]\u0006 קושיה \u0003והוא\u0004 זה שגם \u0003מפרק לה\u0004 \u0005[תירץ אותה\u0006\u0005]:\u0006 מה שרב חסדא העמיד את משנתנו בנזירות מועטת, שמצד אחד אינו סותר מה שנהג כבר נזירות, ומצד אחר אין ימי ספרו וגמרו עולים לו למנין הנזירות, כוונתו כגון \u0003בנזירות בת חמשים יום, דיתיב עשרין\u0004 \u0005[שישב עשרים\u0006\u0005]\u0006 יום בנזירות, \u0003ואיתילידא ביה\u0004 \u0005[ונולדה בו\u0006\u0005]\u0006 \u0003צרעת,\u0004 ואז \u0003מגלח\u0004 על \u0003צרעתו, והדר יתיב תלתין יומין\u0004 \u0005[וחוזר\u0006 ויושב שלושים ימים\u0005]\u0006 של \u0003נזיר.\u0004 ואין עוד להקשות: והרי בנזירות מועטת צריך גידול שיער, \u0003דהא אית ליה\u0004 \u0005[שהרי יש לו\u0006\u0005]\u0006 בסוף מניינו \u0003גידול שער\u0004 במשך שלושים יום.","\u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רמי בר חמא,\u0004 שנינו במשנה: \u0003נזיר שהיה טמא\u0004 טומאת מת \u0003בספק,\u0004 שלא ברור אם אכן נטמא, \u0003ומוחלט בספק,\u0004 שנצטרע, וספק אם נעשה מצורע מוחלט,"],["\u0003אוכל בקדשים לאחר ששים יום\u0004 שיצא בהם מידי ספק טומאת צרעת,","\u0003ושותה יין ומיטמא למתים לאחר מאה ועשרים יום\u0004 שהשלים כל חובת נזירותו. שאם בא מיד לגלח משום צרעת, אומרים לו שצריך להמתין — שמא נזיר טהור הוא, ואין ספק צרעת דוחה נזירות. ובסוף שלושים יום מגלח משום ספק תגלחת מצורע ספק תגלחת נזיר טהור. וכשרוצה לגלח שוב לאחר שבעה ימים לתגלחת שניה של צרעתו — אינו יכול לגלח, שמא לא היה מצורע אלא טמא, והתגלחת שעשה היתה תגלחת טומאה, ולכן חלה עליו נזירות טהרה, וצריך לשמור נזירות עד שלושים יום. ובסוף ימים אלה, דהיינו ביום השישים, מגלח, ומותר למחרת באכילת קדשים, שהרי גם אם היה מצורע מוחלט — גילח פעמיים. אבל עדיין אינו מותר מנזירותו — שמא היה מצורע מוחלט, ושתי תגלחות אלה היו לשם תגלחות הצרעת. ולכן מונה עוד שלושים יום ומגלח, ביום התשעים, אלא שאז אומרים לו: אינך יכול עדיין לשתות יין ולהיטמא למתים, שמא היית טמא, ותגלחת שלישית זו — תגלחת טומאה היתה. ולכן צריך למנות עוד שלושים יום לנזירות טהרה, ובסוף אלה (שהם מאה ועשרים יום לתחילת נזירותו) יכול לגלח תגלחת טהרה ולשתות יין ולהיטמא למתים.","\u0003ותני עלה\u0004 \u0005[ושנו על כך\u0006\u0005]:\u0006 \u0003במה דברים אמורים —\u0004 \u0003בנזירות מועטת\u0004 של שלושים יום, \u0003אבל בנזירות בת שנה —\u0004 \u0003אוכל בקדשים לאחר שתי שנים,\u0004 שאינו מגלח אלא רק לאחר שנה — שמא אינו מצורע, ומגלח שוב רק לאחר שנה שניה — שמא היה טמא, וזו נזירות טהרתו. ומכל מקום אם היה מצורע מוחלט יכול לאכול מעתה בקדשים, שהרי נהג שתי תגלחות, אלא שלא גילח כלל לנזירותו, ולכן נוהג נזירות שנה נוספת, ומגלח, ונוהג שוב נזירות שנה, שמא היתה התגלחת השלישית תגלחת טומאה, וזו תגלחת טהרה.","\u0003ושותה יין ומיטמא למתים לאחר ארבע שנים.\u0004","\u0003ואי סלקא דעתך סלקין ליה יומי\u0004 \u0005[ואם עולה על דעתך\u0006 שעולים לו הימים\u0005]\u0006 שהיה טמא בהם למנין ימי נזירותו — \u0003תיסגי ליה\u0004 \u0005[יהא די לו\u0006\u0005]\u0006 \u0003בשלש שנים ושלשים יום!\u0004 שמספק אינו יכול לגלח לצרעתו אלא בסוף שנה (שמא נזיר טהור הוא) ולתגלחת שניה צריך להמתין עוד שנה (שמא נזיר טמא היה). אבל אז, אם ימי ספרו עולים לו לנזירותו כדברי רב חסדא, יכול היה להמתין שלושים יום (כדי גידול שיער) ולגלח לנזירות הטומאה, ואחר יוסיף עוד שנה לנזירות טהרה. ומזה שמחייבים אותו להמתין ארבע שנים משמע שאין ימי צרעתו עולים לו לנזירות.","\u0003ועוד מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רב אשי\u0004 ממדרש הלכה, ששנינו בו: \u0003אין לי אלא ימי טומאה שאין עולין לו מן המנין\u0004 של נזירות, ואולם \u0003ימי חלוטו\u0004 שהיה כבר מצורע מוחלט, \u0003מנין\u0004 שאף הם אינם עולים לו למנין ימי נזירות? \u0003ו\u0004לכאורה \u0003דין הוא,\u0004 כלומר, כך יש לומר מסברה: \u0003ימי טומאה מגלח ומביא קרבן, וימי חלוטו\u0004 גם כן \u0003מגלח ומביא קרבן\u0004 לצרעתו, \u0003מה ימי טומאתו אין עולין לו מן המנין —\u0004 \u0003אף ימי חלוטו אין עולין לו מן המנין.\u0004","ויש לדחות: \u0003לא, אם אמרת\u0004 הלכה זו דווקא \u0003בימי טומאתו שכן\u0004 יש בהם גם הלכה נוספת ש\u0003מבטל בהן את הקודמים, תאמר בימי חלוטו שאין מבטל בהן את הקודמין,\u0004 כפי ששנינו במשנתנו.","ולכן צריך להביא ראיה אחרת, \u0003אמרת: קל וחומר הוא; ומה נזיר בקבר\u0004 (בבית קברות) שנדר נזירות כשהוא עומד במקום טמא, \u0003ששערו ראוי לתגלחת נזירות,\u0004 בכל זאת ימים שהיה טמא בהם \u0003אין עולין לו מן המנין, ימי חלוטו\u0004 שבהם הוא מצורע מוחלט, \u0003שאין שערו ראוי לתגלחת נזירות\u0004 שהרי קודם צריך לגלחם תגלחת מצורע — \u0003לא כל שכן\u0004 שלא יעלו לו לנזירותו?!","\u0003ואין לי אלא ימי חלוטו. ימי ספרו,\u0004 שסופר אחר כך כדי להיטהר מטומאת צרעת, \u0003מנין\u0004 שאין עולים מן המניין? \u0003ודין הוא,\u0004 שאפשר ללמוד זאת מסברה:"],["\u0003מה ימי חלוטו טעון\u0004 בהם \u0003תגלחת —\u0004 \u0003אף ימי ספרו\u0004 טעון תגלחת, \u0003ו\u0004משום כך \u0003מה ימי חלוטו אין עולין לו מן המנין —\u0004 \u0003אף ימי ספרו\u0004 אין עולים לו.","\u0003יכול אף ימי הסגרו\u0004 (הימים שהיה בהם מצורע מוסגר) דינם \u0003כן\u0004 שאינם עולים לו? \u0003והדין נותן\u0004 שכך יהיה, שהרי כך יש להשוותם: מצורע \u0003חלוט\u0004 (מוחלט) \u0003מטמא משכב ומושב, ו\u0004מצורע ב\u0003ימי הסגרו\u0004 גם הוא \u0003מטמא משכב ומושב,\u0004 ולפיכך \u0003אם למדת לימי חלוטו שאין עולין לו מן המנין —\u0004 \u0003אף ימי הסגרו\u0004 יש לומר ש\u0003אין עולין לו מן המנין.\u0004","ויש לדחות, \u0003אמרת: לא, אם אמרת\u0004 הלכה זו דווקא \u0003בימי חלוטו —\u0004 \u0003שכן חלוטו\u0004 אם היה מצורע מוחלט ונרפא \u0003טעון\u0004 (חייב) \u0003תגלחת ומביא קרבן\u0004 קודם שיתחיל נזירותו, \u0003לפיכך אין עולין\u0004 הימים הללו לנזירותו. \u0003תאמר בימי הסגרו שאין טעון תגלחת ואינו מביא קרבן, לפיכך יעלו למנין.\u0004","\u0003מכאן אמרו: ימי ספרו\u0004 של מצורע, \u0003וימי גמרו\u0004 (שהוא מצורע גמור, מוחלט) — \u0003אין עולין לו מן המנין. אבל ימי\u0004 טומאת \u0003הזב והזבה, ו\u0004ימי \u0003הסגרו של מצורע —\u0004 \u0003הרי אלו עולין לו.\u0004","ולענייננו, \u0003קתני מיהת\u0004 \u0005[שנה על כל פנים\u0006\u0005]:\u0006 \u0003לא, אם אמרת בימי טומאה שכן מבטל בהן את הקודמין, תאמר בימי חלוטו\u0004 שאין מבטל בהם את הקודמים. ונברר: \u0003במאי\u0004 \u0005[במה\u0006\u0005]\u0006 מדובר כאן שאין ימי חילוטו מבטלים את הקודמים? \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 \u0003בנזירות מועטת\u0004 שאין בה אלא שלושים יום, אי אפשר לומר זאת, \u0003הא בעינן\u0004 \u0005[\u0006שהרי צריכים אנו\u0005]\u0006 \u0003גידול שער\u0004 של שלושים יום לאחר שיטהר.","\u0003אלא לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 מדובר שם \u0003בנזירות מרובה, וקתני\u0004 \u0005[ו\u0006אף על פי כן שנה\u0005]\u0006 \u0003שאין עולין לו מן המנין. אלמא\u0004 \u0005[מכאן\u0006\u0005]\u0006 ש\u0003לא סלקין ליה\u0004 \u0005[עולים לו\u0006\u0005]\u0006 ימי חילוטו למנין הנזירות. שלא כדברי רב חסדא! ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכן הוא, ונדחו דברי רב חסדא.","\u0003אמר ר' אליעזר משום\u0004 (בשם) \u0003ר' יהושע: כל טומאה מן המת שנזיר\u0004 שנטמא בה דינו ש\u0003מגלח עליה\u0004 — הכל \u0003חייבין עליה על ביאת מקדש,\u0004 שאם נכנס טמא בטומאה כזו למקדש — חייב משום טמא הנכנס לקודש. \u0003וכל טומאה מן המת שאין הנזיר מגלח עליה —\u0004 \u0003אין חייבין עליה על ביאת מקדש.\u0004","\u0003אמר ר' מאיר: לא תהא זו\u0004 טומאת המת שאין הנזיר מגלח עליה \u0003קלה מן\u0004 טומאת \u0003השרץ,\u0004 והרי מפורש בתורה שטמא שרץ חייב על ביאת מקדש.","תחילה מבררים את מסורתה של ההלכה במשנה. \u0003ור' אליעזר\u0004 האם \u0003משום ר' יהושע\u0004 (בן חנניה) \u0003גמר לה\u0004 \u0005[למד אותה\u0006\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003משום ר' יהושע בר ממל גמר לה\u0004 \u0005[למד אותה\u0006\u0005].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אליעזר: כשהלכתי ל\u0004מקום הנקרא \u0003ערדסקיא מצאתי את ר' יהושע בן פתר ראש שהיה יושב ודן לפני ר' מאיר\u0004 \u0003בהלכה,\u0004 ואומר: \u0003כל טומאה מן המת שהנזיר מגלח עליה —\u0004 \u0003חייבין עליה משום ביאת מקדש, וכל טומאה מן המת שאין הנזיר מגלח עליה —\u0004 \u0003אין חייבין עליה משום ביאת מקדש. אמר לו\u0004 ר' מאיר: \u0003אל תהא זו\u0004 טומאה מן המת שאין מגלחים עליה \u0003קלה משרץ.\u0004","\u0003אמרתי לו\u0004 לר' מאיר: \u0003כלום אתה בקי\u0004 (מכיר) \u0003בר' יהושע בר ממל? אמר לי: הן.\u0004 אמרתי לו: \u0003כך אמר לי ר' יהושע בר ממל משום ר' יהושע\u0004 (בן חנניה): \u0003כל טומאה מן המת שהנזיר מגלח עליה —\u0004 \u0003חייב עליה משום ביאת מקדש, וכל טומאה מן המת שאין הנזיר מגלח עליה —\u0004 \u0003אין חייבין עליה משום ביאת מקדש.\u0004 עד כאן לשון הברייתא. \u0003הוי\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003משום ר' יהושע בר ממל גמיר לה\u0004 \u0005[למד אותה\u0006\u0005]\u0006 ר' אליעזר, ולא למדה במישרין מר' יהושע!","\u0003אמרו: שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כלל זה: \u0003כל שמעתתא\u0004 \u0005[שמועה,\u0006 הלכה\u0005]\u0006 \u0003דמתאמרה בבי תלתא\u0004 \u0005[שנאמרת\u0006 על ידי מסורת של שלושה אנשים\u0005]\u0006 \u0003קדמאי ובתראי\u0004 \u0005[\u0006את הראשונים ואת האחרונים\u0005]\u0006 בשלשלת המסורת — \u0003אמרינן\u0004 \u0005[אנו אומרים\u0006\u0005],\u0006 \u0003מציעאי\u0004 \u0005[את האמצעיים\u0006\u0005] —\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים\u0006\u0005],\u0006 ולכן נשנו במשנתנו רק שמו של ר' אליעזר (האחרון במסורת זו) ור' יהושע בן חנניה (הראשון במסורת זו), ואילו שמו של ר' יהושע בן ממל (האמצעי) לא הוזכר.","\u0003אמר רב נחמן בר יצחק: אף אנן נמי\u0004 \u0005[אנו גם כן\u0006\u0005]\u0006 כך \u0003תנינא\u0004 \u0005[שנינו\u0006\u0005],\u0006 \u0003אמר נחום הלבלר: כך מקובלני מר' מיאשא שקיבל מאבא, שקבל מן הזוגות, שקבלו מן הנביאים: הלכה למשה מסיני בזורע\u0004 צמחי \u0003שבת וחרדל בשנים ושלשה מקומות\u0004 נבדלים בתוך שדה אחד, \u0003שנותן\u0004 (מניח) \u0003פאה מכל אחד ואחד\u0004 ממינים אלו לעצמו, ולא יתן פאה אחת עבור כולם.","\u0003ואילו\u0004 את שמם של \u0003יהושע וכלב לא קחשיב\u0004 \u0005[מנה\u0006\u0005],\u0006 אף על פי שהם היו הזקנים שמסרו ממשה לנביאים. \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכששונים מסורת אין מונים את כל האנשים שמסרוה.","ועוד בענין טומאות שנזיר מגלח עליהן. \u0003אמר ר' עקיבא: דנתי\u0004 בהלכה \u0003לפני ר' אליעזר\u0004 והעליתי בפניו קל וחומר זה: \u0003מה אם עצם כשעורה שאינו מטמא אדם באהל —\u0004 \u0003הנזיר מגלח על מגעו ועל משאו, רביעית דם שהוא\u0004 חמור ממנה שהוא \u0003מטמא אדם באהל —\u0004 \u0003אינו דין שיהא הנזיר מגלח על מגעה ועל משאה?\u0004","\u0003אמר לי: מה זה עקיבא?! אין דנין כאן\u0004 במקרה זה \u0003מקל וחומר.\u0004 ולא הסביר מדוע אין דנים. \u0003וכשבאתי והרציתי דברים\u0004 אלו \u0003לפני ר' יהושע, אמר לי: יפה אמרת\u0004 מצד הסברה שבדבר, \u0003אלא כן אמרו: הלכה\u0004 מקובלת היא ואין לפורכה משום קל וחומר."],["על האמור במשנה \"הלכה\" \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 מה הכוונה? האם \u0003עצם כשעורה\u0004 היא \u0003הלכה\u0004 למשה מסיני שנזיר מגלח עליה, \u0003ורביעית דם\u0004 רצה ר' עקיבא ללמוד ממנה בדרך \u0003קל וחומר, ו\u0004הוא שאמרו \u0003אין דנין קל וחומר מהלכה;\u0004","\u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003רביעית דם הלכה\u0004 שמטמאה באוהל, \u0003ו\u0004רצה ללמוד מ\u0003עצם כשעורה\u0004 ב\u0003קל וחומר\u0004 שנזיר אף מגלח על רביעית, \u0003ואין דנין קל וחומר מהלכה?\u0004 ומציעים פתרון לשאלה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לשאלה זו ממה ששנינו ברייתא מפורשת: \u0003עצם כשעורה הלכה, ורביעית דם קל וחומר, ואין דנין קל וחומר מהלכה.\u0004","","\u0003שני נזירים שאמר להן אחד \"ראיתי אחד מכם שנטמא, ואיני יודע איזה מכם\u0004 הוא\" — הרי שניהם משלימים את ימי הנזירות ו\u0003מגלחין\u0004 בסוף ימי הנזירות, \u0003ומביאין\u0004 מספק \u0003קרבן טומאה וקרבן טהרה. ואומר\u0004 אחד מהם לחבירו: \u0003אם אני הוא\u0004 ה\u0003טמא —\u0004 \u0003קרבן טומאה שלי וקרבן טהרה שלך, ואם אני הוא הטהור —\u0004 \u0003קרבן טהרה שלי, וקרבן טומאה שלך.\u0004","\u0003וסופרין\u0004 שניהם מספק עוד \u0003שלשים יום\u0004 של נזירות, \u0003ומביאין קרבן טהרה, ואומר\u0004 אחד מהם: \u0003אם\u0004 אף \u0003הוא הטמא\u0004 — אותו \u0003קרבן טומאה\u0004 שהוקרב בפעם הקודמת היה \u0003שלי וקרבן טהרה שלך, וזה\u0004 הקרבן שמקריבים עכשיו — \u0003קרבן טהרתי\u0004 הוא. \u0003ואם אני הוא הטהור —\u0004 \u0003קרבן טהרה\u0004 שהוקרב קודם — \u0003שלי\u0004 היה, \u0003וקרבן טומאה שלך\u0004 היה, \u0003וזה\u0004 שמקריבים כעת הוא \u0003קרבן טהרתך.\u0004","\u0003קתני\u0004 \u0005[שנה\u0006\u0005]\u0006 במשנה: \u0003שני נזירים שאמר להם\u0004 אחד \u0003\"ראיתי אחד מכם שנטמא, ואיני יודע איזה מכם\".\u0004 ותוהים על עצם הענין: \u0003ואמאי\u0004 \u0005[ומדוע\u0006\u0005]\u0006 ייחשבו שני אלה לטמאים? הלא את ההלכה ש\u0003כל ספק טומאה ברשות היחיד\u0004 שהוא טמא \u0003מהיכא ילפינן לה\u0004 \u0005[מהיכן אנו לומדים אותה\u0006\u0005] —\u0006 \u0003מסוטה.\u0004","אך אין ענין הסוטה דומה לענייננו, שכן יש לומר: \u0003מה סוטה\u0004 שספק אם נבעלה ונטמאה, יש \u0003בועל ונבעלת\u0004 בלבד, \u0003אף כל ספק טומאה ברשות היחיד\u0004 יהא טמא דווקא \u0003כגון דאיכא בי תרי\u0004 \u0005[שיש שנים\u0006\u0005]\u0006 בלבד. \u0003אבל הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 במשנתנו, הרי מדובר שישנם \u0003שני נזירים והאי דקאי גביהון\u0004 \u0005[וזה שעומד אצלם\u0006\u0005]\u0006 שאמר להם שנטמאו — \u0003הא תלתא\u0004 \u0005[הרי\u0006 איפוא שלושה\u0005],\u0006 אם כן \u0003הוה ליה\u0004 \u0005[הרי זה\u0006\u0005]\u0006 \u0003ספק טומאה ברשות הרבים\u0004 שכן שלושה אנשים הם כבר רבים, \u0003ו\u0004כלל בידינו: \u0003כל ספק טומאה ברשות הרבים —\u0004 \u0003ספיקו טהור!\u0004","\u0003אמר רבה בר רב הונא: באומר \"ראיתי\u0004 מרחוק \u0003טומאה שנזרקה ביניכם\"\u0004 והוא לא היה ביניהם באותו זמן שנטמא אחד מהם, ולא היו שם אלא שניהם בלבד ולכן הרי זה ספק טומאה ברשות היחיד. \u0003אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם כן\u0006\u0005]\u0006 הדבר מן הלשון"],["\u0003דקתני\u0004 \u0005[ש\u0006כן שנה\u0005]\u0006 בדבריו \u0003\"ואיני יודע איזה מכם\"\u0004 משמע שלא היה סמוך להם, שלא יכול היה אפילו להבחין מי מהם נטמא. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכן הוא.","שנינו במשנה ששני הנזירים \u0003\"מגלחין ומביאין\".\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע\u0006\u0005]\u0006 הם מגלחים? והרי \u0003דילמא לאו טמאין אינון\u0004 \u0005[שמא לא טמאים הם\u0006\u0005]\u0006 שניהם, \u0003ו\u0004הרי כל אחד מהם \u0003קעביד\u0004 \u0005[עושה\u0006\u0005]\u0006 \u0003הקפה\u0004 שמקיף פאת ראשו כשמגלח כל שערו שלא לצורך. ואם אינו צריך לגלח נמצא שעובר על איסור לא תעשה! \u0003אמר שמואל:\u0004 מדובר כאן כגון שהיו נזירים אלה \u0003אשה\u0004 שאיננה אסורה בהקפת הראש \u0003ו\u0004כן \u0003קטן\u0004 שאינו חייב במצוות.","את דברי שמואל אלה מבררים: \u0003ולוקמא\u0004 \u0005[ושיעמיד\u0006\u0005]\u0006 את המשנה \u0003בגדול, ו\u0004מותר הדבר מטעם ש\u0003הקפת כל הראש,\u0004 אם מגלח את כל שערות ראשו ולא פאת ראשו בלבד, \u0003לא שמה\u0004 (אינה נחשבת) \u0003הקפה\u0004 שאסורה מן התורה! אלא \u0003מדלא מוקים לה הכי\u0004 \u0005[מ\u0006כיון שאינו מעמיד ומסביר את המשנה כך\u0005]\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003קסבר\u0004 \u0005[סבור\u0006\u0005]\u0006 \u0003שמואל: הקפת כל הראש —\u0004 \u0003שמה הקפה.\u0004","\u0003מר זוטרא מתני לה להא שמעתא דשמואל אסיפא\u0004 \u0005[היה שונה את ההלכה הזו של שמואל על סופה\u0006 של המשנה\u0005]\u0006 להלן: \u0003נזיר שהיה טמא בספק ומוחלט בספק —\u0004 \u0003אוכל בקדשים לאחר ששים יום ומגלח ארבע תגלחות.\u0004 ויש מקום לשאול: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 כיון שהוא ספק ואין זה ברור שחייב בתגלחת \u0003קעביד\u0004 \u0005[עושה\u0006 הוא\u0005]\u0006 בתגלחתו \u0003הקפה\u0004 של הראש שאסורה! \u0003אמר שמואל:\u0004 מדובר \u0003באשה וקטן\u0004 שאינם אסורים בהקפה.","ובענין זה \u0003אמר רב הונא:\u0004 גדול \u0003המקיף את\u0004 פאות ראשו של \u0003הקטן הרי הוא חייב,\u0004 אף שהקטן עצמו אינו חייב במצוות. \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב אדא בר אהבה,\u0004 שהיה סבור שאין בכך איסור, \u0003לרב הונא: ודידך מאן מגלח להון\u0004 \u0005[ו\u0006את הילדים שלך מי מגלח אותם\u0005]\u0006 ומקיף את פאת ראשם? שהרי לשיטתך אסור לגדול להקיף שערו של קטן! \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003חובה\u0004 אשתי. שהיא כאשה איננה אסורה בהקפה. אמר לו רב אדא בר אהבה בתרעומת: \u0003תקברינון\u0004 \u0005[תקבור\u0006\u0005]\u0006 \u0003חובה לבניה\u0004 אם כך היא עושה. ומספרים: \u0003כולהו שני\u0004 \u0005[כל שנותיו\u0006\u0005]\u0006 של \u0003רב אדא בר אהבה לא אקיים ליה זרעא\u0004 \u0005[התקיים לו זרע\u0006\u0005]\u0006 \u0003לרב הונא\u0004 שהיו ילדיו מתים, בגלל ביטוי זה של קללה שיצא מפי רב אדא.","ושואלים: \u0003מכדי תרוייהו סבירא\u0004 \u0005[הרי שניהם\u0006 רב הונא ורב אדא סבורים\u0005]\u0006 ש\u0003הקפת כל הראש שמה הקפה,\u0004 אם כן \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם חלוקים\u0005],\u0006 כלומר, מה טעמו של כל אחד מהם? ומסבירים: \u0003רב הונא\u0004 שאוסר לגדול להקיף לקטן ומתיר לאשה לעשות זאת, \u0003סבר\u0004 \u0005[סבור\u0006\u0005]\u0006 נאמר \u0003\"לא תקיפו פאת ראשכם ולא תשחית\u0004 \u0005[את\u0006\u0005]\u0006 \u0003פאת זקנך\"\u0004 (ויקרא יט, כז) וצירוף האיסורים בכתוב זה בא ללמד: \u0003כל\u0004 מי \u0003שיש לו\u0004 (עליו) איסור \u0003השחתה\u0004 של זקן — \u0003יש לו\u0004 איסור \u0003הקפה, והני נשי\u0004 \u0005[ואלה הנשים\u0006\u0005]\u0006 \u0003הואיל וליתנהו\u0004 \u0005[ואינן\u0006\u0005]\u0006 \u0003ב\u0004כלל איסור \u0003השחתה\u0004 שהרי אין להן זקן, \u0003ליתנהו נמי\u0004 \u0005[אינן גם כן\u0006\u0005]\u0006 \u0003ב\u0004כלל איסור \u0003הקפה.\u0004","\u0003ורב אדא בר אהבה\u0004 שמתיר ככלל להקיף לקטן, \u0003סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003אחד המקיף ואחד הניקף במשמע\u0004 הביטוי הזה של \"לא תקיפו\", כיון שנאמר בלשון רבים. \u0003ו\u0004מתוך כך \u0003איתקש\u0004 \u0005[הוקש\u0006\u0005]\u0006 בפסוק זה \u0003מקיף לניקף, כל היכא\u0004 \u0005[מקום\u0006\u0005]\u0006 ש\u0003ניקף מיחייב\u0004 \u0005[חייב\u0006\u0005]\u0006 — ה\u0003מקיף נמי מיחייב\u0004 \u0005[גם כן חייב\u0006\u0005],\u0006 \u0003והאי קטן\u0004 \u0005[וקטן זה\u0006\u0005]\u0006 \u0003הואיל והוא גופיה\u0004 \u0005[עצמו\u0006\u0005]\u0006 \u0003לאו בר\u0004 \u0005[לא בן\u0006\u0005]\u0006 \u0003עונשין הוא דמיחייב\u0004 \u0005[ש\u0006יהיה חייב\u0005],\u0006 לכן גם אם גדול \u0003מקיף\u0004 את ראשו \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא מיחייב\u0004 \u0005[חייב\u0006\u0005].\u0006","ושואלים: \u0003לימא\u0004 \u0005[האם נאמר\u0006\u0005]\u0006 כי \u0003הקפת כל הראש תנאי\u0004 \u0005[\u0006מחלוקת תנאים\u0005]\u0006 \u0003היא\u0004 אם נחשבת הקפה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006\u0005]:\u0006 מה שנאמר בדיני תגלחת מצורע \u0003\"\u0004יגלח את כל שערו את \u0003ראשו\"\u0004 וגו' (ויקרא יד, ט), \u0003מה תלמוד לומר,\u0004 מה עוד בא ללמדנו הכתוב \"ראשו\"? והרי כבר נאמר \"כל שערו\"! ומסבירים: \u0003לפי שנאמר \"לא תקפו פאת ראשכם\"\u0004 (ויקרא יט, כז),"],["\u0003יכול אף מצורע כן\u0004 יהא אסור בהקפת הראש — \u0003תלמוד לומר\u0004 במפורש: \u0003\"ראשו\"\u0004 (ויקרא יד, ט), שציווה עליו הכתוב לגלח כל ראשו, ונדחה איסור הקפת הראש. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא אחרת\u0005]:\u0006 \u0003\"ראשו\"\u0004 שנאמר במצורע \u0003מה תלמוד לומר? לפי שנאמר גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר \"תער לא יעבר על ראשו\"\u0004 (במדבר ו, ה) \u0003יכול אף נזיר מצורע כן\u0004 שיהיה אסור בתגלחת אף כשהגיע זמן טהרת צרעתו — \u0003תלמוד לומר: \"ראשו\",\u0004 ללמד שאם נצטרע הנזיר צריך לגלח ראשו ככל מצורע.","\u0003מאי לאו תנאי\u0004 \u0005[האם לא\u0006 נאמר שמחלוקת תנאים\u0005]\u0006 \u0003היא\u0004 בכך, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת מי שאומר\u0005]\u0006 שהלימוד מ\"ראשו\" הוא \u0003מנזיר, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003הקפת כל הראש לא שמה הקפה,\u0004 ולכן אין צורך במקרא מיוחד ללמדנו שמותר למצורע לגלח כל ראשו, \u0003וכי אתא קרא\u0004 \u0005[וכאשר בא הכתוב\u0006\u0005]\u0006 \"ראשו\" — הרי זה \u0003למידחי\u0004 \u0005[לדחות\u0006\u0005]\u0006 \u0003את לא תעשה\u0004 (\"תער לא יעבור על ראשו\") \u0003ועשה\u0004 (\"קדוש יהיה גדל פרע שער ראשו\") שיש בנזיר. \u0003ואידך סבר\u0004 \u0005[והאחר סבור\u0006\u0005]:\u0006 \u0003הקפת כל הראש שמה הקפה, וכי אתא קרא\u0004 \u0005[וכאשר בא הכתוב\u0006\u0005]\u0006 במצורע — הרי זה \u0003למידחי לאו גרידא\u0004 \u0005[לדחות לא\u0006 תעשה בלבד\u0005]\u0006 של איסור הקפת הראש?","\u0003אמר רבא\u0004 ודחה הוכחה זו: לא, אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל\u0006\u0005]\u0006 \u0003הקפת כל הראש לא שמה הקפה,\u0004 ואף לדעת התנא שבא הכתוב להתיר את הקפת הראש של מצורע. \u0003וכי אתא קרא\u0004 \u0005[וכאשר בא הכתוב\u0006\u0005]\u0006 במיוחד להתיר דבר זה, הרי זה לאופן מסויים, \u0003כגון שהקיף\u0004 (גילח) קודם את פאות הראש לבדן, \u0003ולבסוף גילח\u0004 את שאר שערותיו, אף שהקפת הפאות לבדן בוודאי אסורה מן התורה. וטעם הפטור הוא: \u0003כיון דאילו גלחיה בחד זימנא\u0004 \u0005[היה מגלח אותו,\u0006 את כל הראש בפעם אחת\u0005] —\u0006 \u0003לא מיחייב\u0004 \u0005[היה מתחייב\u0006\u0005],\u0006 לכן \u0003כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 \u0003הקיף ולבסוף גילח —\u0004 \u0003נמי לא מיחייב\u0004 \u0005[גם כן איננו מתחייב\u0006\u0005].\u0006 שכיון שהותר למצורע לגלח כל ראשו, יכול לעשות זאת בכל דרך שירצה.","ומקשים על סברה זו: \u0003ומי כתב קרא הכי\u0004 \u0005[והאם כותב הכתוב כך\u0006\u0005]\u0006 להתיר לעשות איסור לכתחילה במקום שאין צורך בכך? \u0003והאמר\u0004 \u0005[והרי אמר\u0006\u0005]\u0006 \u0003ריש לקיש: כל מקום שאתה מוצא עשה ולא תעשה\u0004 הסותרים זה את זה, \u0003אם אתה יכול\u0004 לעשות את הדברים ו\u0003לקיים את שניהם —\u0004 \u0003מוטב, ואם לאו\u0004 \u0005[לא\u0006\u0005],\u0006 כשאין כל דרך אחרת — \u0003יבוא עשה וידחה את לא תעשה.\u0004 ואם אפשר שהנזיר יגלח כל הראש בהיתר גמור (אם הקפת כל הראש אינה אסורה) אין לומר שהתורה מתירה לעשות זאת בדרך שיש בה דחיית הלאו.","\u0003אלא\u0004 יש לחזור מן ההסבר הקודם, ועם זאת לדחות את הסברה שיש מחלוקת לגבי הקפת כל הראש, אלא לומר להיפך: \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל\u0006\u0005]\u0006 \u0003הקפת כל הראש שמה הקפה.\u0004 על כך שואלים: לדרך זו פשוטה השיטה ש\"ראשו\" בא להתיר הקפת כל הראש במצורע, ומכאן למדנו כי עשה דוחה לא תעשה. אבל \u0003ומאן דמוקים לקרא למידחי\u0004 \u0005[ומי שמעמיד את הכתוב\u0006 \"ראשו\" כדי לדחות\u0005]\u0006 \u0003לא תעשה ועשה\u0004 בנזיר, \u0003לאו גרידא מנליה\u0004 \u0005[לאו בלבד מניין לו\u0006\u0005]\u0006 שעשה דוחה אותו?","ומשיבים: \u0003יליף\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 דבר זה \u0003מגדילים,\u0004 כלומר, מציצית. ומה הוא לימוד זה — ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"לא תלבש שעטנז\"\u0004 (דברים כב, יא) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"לא תלבש שעטנז\"\u0004 בדרך כלל, אבל מסמיכות הכתובים למדים אנו — \u0003הא\u0004 (אבל) \u0003\"גדילים תעשה לך\"\u0004 (דברים כב, יב) \u0003מהם,\u0004 אפילו משעטנז. ללמדנו שדוחה מצות עשה של ציצית את איסור שעטנז.","ושואלים: \u0003ומאן דנפקא ליה\u0004 \u0005[ומי שיוצא לו\u0006\u0005]\u0006 לימוד זה \u0003מ\"ראשו\"\u0004 האמור במצורע, ומכאן למדים שעשה דוחה את לא תעשה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 \u0003לא נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004הכתוב ב\u0003גדילים\u0004 והוא נזקק להוכחה נוספת? ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול הוא לומר לך\u0005]:\u0006 המקרא הזה לגבי גדילים \u0003ל\u0004כמו שאמר \u0003רבא הוא דאתא\u0004 \u0005[שבא\u0006\u0005]\u0006 ולא כדי ללמוד שעשה דוחה את לא תעשה.","ש\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 \u0003\"ונתנו על ציצת הכנף\u0004 פתיל תכלת\u0003\"\u0004 (במדבר טו, לח) והצירוף \"ציצית הכנף\" בא ללמד שהציצית תהא \u0003מין כנף,\u0004 מאותו סוג בגד שעשויה ממנו הטלית, ועליה יתנו \u0003\"פתיל תכלת\". וכתיב\u0004 \u0005[ונאמר\u0006\u0005]\u0006 \u0003\"\u0004לא תלבש שעטנז \u0003צמר ופשתים יחדו\"\u0004 (דברים כב, יא) וסמוך לו \"גדילים תעשה לך\", ללמד שצריך לעשות ציציות מצמר ופשתים.","\u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003כיצד\u0004 מיישבים את הסתירה בין מה שאמרו שתהא הציצית ממין הכנף, ובין האמור שתהא הציצית מצמר ופשתים? ציציות של \u0003צמר ופשתים\u0004 — \u0003פוטרים\u0004 (יוצאים בהן ידי חובה) \u0003בין במינן\u0004 בצמר ופשתים, \u0003בין\u0004 ש\u0003לא במינן\u0004 בשאר מיני אריג. ואילו ציציות של \u0003שאר מינין, במינן —\u0004 \u0003פוטרין,\u0004 ש\u0003לא במינן —\u0004 \u0003אין פוטרין.\u0004 ולשיטה זו אין למדים מכאן לימוד אחר שעשה דוחה לא תעשה.","ושואלים עוד: \u0003והאי\u0004 \u0005[ואותו\u0006\u0005]\u0006 \u0003תנא דמפיק ל\"ראשו\" ללאו גרידא\u0004 \u0005[שמוציא את\u0006 הכתוב \"ראשו\" לכך שעשה דוחה לאו בלבד\u0005],\u0006 הדין \u0003דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 \u0003עשה\u0004 של תגלחת מצורע \u0003ודחי\u0004 \u0005[ודוחה\u0006\u0005]\u0006 \u0003את לא תעשה ועשה\u0004 של נזיר \u0003מנלן\u0004 \u0005[מניין לנו\u0006\u0005]?\u0006 מנין יודע הוא שתורת תגלחת מצורע חלה גם על נזיר שהצטרע? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\"זקנו\".\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003\"זקנו\"\u0004 (ויקרא יד, ט) האמור במצורע מיותר, שהרי כבר נאמר \"כל שערו\", \u0003מה תלמוד לומר\u0004 \"זקנו\"? \u0003לפי שנאמר\u0004 בכהנים \u0003\"ופאת זקנם לא יגלחו\"\u0004 (ויקרא כא, ה) \u0003יכול אף כהן מצורע כן\u0004 שאסור לו לגלח את זקנו — \u0003תלמוד לומר: \"זקנו\",\u0004 שהורתה התורה לכל מצורע, גם אם הוא כהן, שיגלח גם את זקנו. ויש בכך ביטול מצוות לא תעשה (\"לא יגלחו\") ומצות עשה של \"קדושים יהיו\" (ויקרא כא, ו), ומכאן הוא למד אף לנזיר שנצטרע, שיש בו לא תעשה ועשה.","ושואלים: \u0003ומאן דמפיק ליה\u0004 \u0005[ומי שמוציא אותו\u0006\u0005]\u0006 כתוב של \u0003\"ראשו\"\u0004 לדחות \u0003לעשה ולא תעשה\u0004 שבנזיר, \u0003לילף\u0004 \u0005[שילמד\u0006\u0005]\u0006 דבר זה \u0003מ\"זקנו\"\u0004 שעשה של תגלחת דוחה עשה ולא תעשה! ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה סבור שאפשר ללמוד מ\"זקנו\" שעשה דוחה לא תעשה ועשה שבנזיר, אם כן \u0003דקיימא לן בעלמא\u0004 \u0005[שמוחזק לנו בכלל\u0006\u0005]\u0006"],["ש\u0003לא אתי\u0004 \u0005[בא\u0006\u0005]\u0006 \u0003עשה ודחי\u0004 \u0005[ודוחה\u0006\u0005]\u0006 \u0003את לא תעשה ועשה, לילף\u0004 \u0005[שילמד\u0006\u0005]\u0006 \u0003מכהן,\u0004 כלומר, ממה שמותר למצורע כהן להתגלח \u0003דדחי\u0004 \u0005[שדוחה\u0006\u0005]\u0006 גם איסור לאו וגם איסור עשה!","\u0003אלא,\u0004 יש לומר ש\u0003מכהן לא ילפינן\u0004 \u0005[אין אנו למדים\u0006\u0005]\u0006 לשאר דיני התורה, ומדוע — שכן יש להשיב על כך: \u0003מה לכהן\u0004 שיש צד של קולא באיסורים שבו — \u0003שכן לאו\u0004 הוא \u0003שאינו שוה בכל,\u0004 שהרי איסוריו של הכהן מיוחדים רק לכהנים, ולא לכל ישראל. לפיכך, מאותו טעם \u0003נזיר מכהן נמי לא יליף\u0004 \u0005[גם כן אינו נלמד\u0006\u0005]\u0006 \u0003שכן לאו\u0004 של כהנים לאו \u0003שאינו שוה בכל\u0004 הוא, ואילו נזירות לכל ניתנה. ולכן צריך היה לימוד מיוחד מ\"ראשו\" שתגלחת מצורע דוחה עשה ולא תעשה של נזיר.","ושואלים מן הצד ההפוך: \u0003ומאן דמוקים להאי\u0004 \u0005[ומי שמעמיד את זה,\u0006 את הכתוב\u0005]\u0006 \u0003\"ראשו\" בנזיר,\u0004 שלומד שעשה דוחה במקרים מסויימים גם לא תעשה ועשה, ובכללם כהן שנצטרע, \u0003למה לי \"זקנו\"?\u0004","ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך\u0006 הוא לו\u0005]\u0006 ללמוד שתגלחת המצורע נעשית בתער דווקא, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 זה שנאמר \u0003\"זקנו\" מה תלמוד לומר? לפי שנאמר \"ופאת זקנם לא יגלחו\"\u0004 (ויקרא כא, ה) \u0003יכול אף כהן מצורע כן, תלמוד לומר\u0004 בהדגשה \u0003\"זקנו\"\u0004 להודיענו שאף כהן מגלח זקנו.","ועדיין יש לברר: \u0003ומנלן\u0004 \u0005[ומניין לנו\u0006\u0005]\u0006 שגילוח מצורע הוא \u0003בתער —\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 נאמר בכהנים \u0003\"ופאת זקנם לא יגלחו\"\u0004 (ויקרא כא, ה) \u0003יכול אף גילחו\u0004 את הזקן \u0003במספרים יהא חייב —\u0004 \u0003תלמוד לומר: \"ולא תשחית\u0004 את פאת זקנך\u0003\"\u0004 (ויקרא יט, כז), שאין האיסור אלא בהשחתת הזקן עד שורשו. \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003לא תשחית\u0004 דווקא, \u0003יכול ליקטן\u0004 (הוציאן) את שערותיו \u0003במלקט\u0004 שעוקר ותולש, \u0003וברהיטני\u0004 (מעין מקצוע קטן) יהא \u0003חייב\u0004 משום השחתה —","\u0003תלמוד לומר: \"ופאת זקנם לא יגלחו\"\u0004 שאין האיסור אלא בגילוח. ומשני הכתובים יחד נלמד: \u0003איזו גילוח שיש בו השחתה —\u0004 \u0003הוי אומר זה תער.\u0004 וכיון שהוצרך הכתוב להתיר גילוח הזקן למצורע, למדים שהמצורע חייב לגלח שערו בתער דוקא, שיש בכך עקירת לא תעשה של גילוח, ולשם כך נאמרה המלה \"זקנו\" במצורע.","ועוד שואלים: \u0003ומאן דמפיק ליה להאי\u0004 \u0005[ומי שמוציא את זה\u0006\u0005]\u0006 הכתוב \u0003\"ראשו\" ל\u0004כך שעשה דוחה \u0003לאו גרידא\u0004 \u0005[בלבד\u0006\u0005],\u0006 של הקפה \u0003למה לי למיכתב\u0004 \u0005[לכתוב\u0006\u0005]\u0006 \u0003\"ראשו\", ולמה לי למיכתב\u0004 \u0005[לכתוב\u0006\u0005]\u0006 \u0003\"זקנו\"?\u0004 והרי אם למדנו מ\"זקנו\" שדוחה עשה ולא תעשה, כל שכן שידחה לא תעשה לבד!","ומשיבים: כוונת הדברים היא שבכל אחד משני כתובים אלה, \"ראשו\" ו\"זקנו\", \u0003משמע\u0004 \u0005[משמעות\u0006\u0005]\u0006 הדברים באה \u0003למידחי\u0004 \u0005[לדחות\u0006\u0005]\u0006 \u0003לאו גרידא\u0004 \u0005[בלבד\u0006\u0005],\u0006 \u0003ו\u0004באותה מידה \u0003משמע למידחי\u0004 \u0005[משמעות\u0006 הדברים באה לדחות\u0005]\u0006 \u0003לא תעשה ועשה,\u0004 שהרי הכתוב עצמו מדבר בלשון כללית ואינו מפרש שהמצוה מתייחסת לאדם מסויים, אלא לכל מי שחל עליו חיוב זה (ואפילו היה כהן או נזיר). \u0003הילכך\u0004 (על כן) כיון שאין אנחנו יודעים על מה מדבר כל כתוב — \u0003שקול הוא ויבואו שניהן,\u0004 שני מקראות, שאחד מהם מלמדנו לענין נזיר, והשני לענין כהן.","ולא ניתן היה להסתפק באחד משני הכתובים וממנו ללמוד לאחר שיבוא עשה וידחה לא תעשה, שכן \u0003כהן מנזיר לא יליף\u0004 \u0005[אינו למד\u0006\u0005],\u0006 \u0003שכן\u0004 יש צד קולא בנזיר שהנזיר \u0003ישנו בשאלה,\u0004 שהוא יכול ללכת לחכם ולהישאל על נדרו ויתיר לו. \u0003נזיר מכהן לא יליף\u0004 \u0005[אינו למד\u0006\u0005]\u0006 \u0003שכן לאו שאינו שוה בכל.\u0004 ומעירים: \u0003ובעלמא לא ילפינן מינייהו\u0004 \u0005[ובכלל,\u0006 לגבי דברים אחרים אין אנו למדים מהם\u0005]\u0006 שעשה דוחה לא תעשה ועשה, \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום להקשות ולשבור\u0005]\u0006 אפשרות זו \u0003כדאמרן\u0004 \u0005[כפי שאמרנו\u0006\u0005]\u0006 מפני נימוקים אלה עצמם.","\u0003אמר רב: מיקל אדם\u0004 שאינו נזיר \u0003כל\u0004 שיער \u0003גופו בתער,\u0004 שאם סובל אדם מריבוי שערו, רשאי הוא לגלח את שערות גופו ואין בדבר איסור, מלבד זקנו ופאות ראשו. \u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 על כך ממה ששנינו בברייתא: איש \u0003המעביר\u0004 (המספר) שער \u0003בית השחי ובית הערוה —\u0004 \u0003הרי זה לוקה\u0004 משום \"ולא ילבש גבר שמלת אשה\" (דברים כב, ה), שכך היא דרכן של נשים לעשות!","ומשיבים: \u0003הא\u0004 \u0005[זה\u0006\u0005]\u0006 שאמרו שלוקה, מדובר במי שמעביר שערות אלה — \u0003בתער, הא\u0004 \u0005[זה\u0006\u0005]\u0006 שאמר רב שמותר — הרי זה \u0003במספרים,\u0004 שאין בהן איסור. ומקשים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003רב נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003בתער קאמר\u0004 \u0005[אמר\u0006\u0005]\u0006 שמותר! ומשיבים: לא תער ממש, אלא \u0003כעין תער\u0004 אמר, וכוונתו שמותר לגזור במספריים סמוך לעור, כעין גילוח התער.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 איש \u0003המעביר\u0004 שער \u0003בית השחי ובית הערוה לוקה. מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 על כך: \u0003העברת שיער\u0004 שעושים אנשים \u0003אינה\u0004 אסורה \u0003מדברי תורה אלא מדברי סופרים\u0004 (חכמים). אם כן מדוע לוקה? ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 פירוש \u0003\"לוקה\" נמי דקאמר\u0004 \u0005[גם כן שאמר\u0006\u0005]\u0006 ר' יוחנן — כוונתו שלוקה \u0003מדרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005],\u0006 שמלקים אותו מכות מרדות, מפני שעבר על דברי סופרים."],["\u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006\u0005]\u0006 גרסה אחרת בהלכה זו: \u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 גבר \u0003המעביר\u0004 שיער \u0003בית השחי ובית הערוה לוקה משום\u0004 \"ו \u0003לא ילבש גבר שמלת אשה\"\u0004 (דברים כב, ה). \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003העברת שיער אינה\u0004 אסורה \u0003מדברי תורה אלא מדברי סופרים,\u0004 וכיצד אם כן אומר ר' יוחנן שלוקה משום שעבר על איסור תורה? ומשיבים: \u0003הוא\u0004 ש\u0003אמר כי האי תנא\u0004 \u0005[כ\u0006דעת תנא זה\u0005],\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המעביר\u0004 שיער \u0003בית השחי ובית הערוה —\u0004 \u0003הרי זה עובר משום\u0004 \"ו \u0003לא ילבש גבר שמלת אשה\".\u0004","שואלים: \u0003ותנא קמא\u0004 \u0005[והתנא הראשון\u0006\u0005]\u0006 שאינו סבור כן, \u0003האי\u0004 \u0005[\u0006את הכתוב הזה\u0005]\u0006 \u0003\"לא ילבש גבר\", מאי דריש ביה\u0004 \u0005[מה\u0006 הוא דורש, לומד, בו\u0005]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך הוא לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"לא יהיה כלי גבר על אשה...\u0004 כי תועבת ה' אלהיך כל עושה אלה\u0003\"\u0004 (דברים כב, ה), ויש לברר: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003תלמוד לומר? אם\u0004 לומר שהכוונה רק ש\u0003לא ילבש איש שמלת אשה, ואשה\u0004 לא תלבש \u0003שמלת איש —\u0004 \u0003הרי כבר נאמר\u0004 בטעמו של איסור זה \u0003\"תועבה היא\" ו\u0004אילו בלבישה בלבד \u0003אין כאן תועבה.\u0004","\u0003אלא\u0004 הכוונה היא ש\u0003לא ילבש איש שמלת אשה\u0004 ומתוך כך ילך \u0003וישב בין הנשים, ואשה\u0004 לא תלבש \u0003שמלת איש ותשב בין האנשים. ר' אליעזר בן יעקב אומר: מנין\u0004 ש\u0003לא תצא אשה בכלי זיין למלחמה —\u0004 \u0003תלמוד לומר: \"לא יהיה כלי גבר על אשה ולא ילבש גבר שמלת אשה\",\u0004 כלומר, \u0003שלא יתקן איש בתיקוני\u0004 (תמרוקי) \u0003אשה\u0004 ובקישוטיה, וכן אשה אסורה במלחמה ובכלי מלחמה, שהם מיוחדים לגברים. וכשיטה זו הולך ר' יוחנן.","\u0003אמר רב נחמן: בנזיר מותר\u0004 לגלח את שיער בית השחי. ומעירים: \u0003ולית הילכתא כוותיה\u0004 \u0005[ואין הלכה כמותו\u0006\u0005].\u0006 מספרים: \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים\u0006\u0005]\u0006 \u0003לר' שמעון בר אבא: חזינא ליה\u0004 \u0005[ראינו אותו\u0006\u0005]\u0006 את \u0003ר' יוחנן דלית ליה\u0004 \u0005[שאין לו\u0006\u0005]\u0006 שערות בית השחי, והרי הוא עצמו אמר שאסור הדבר! \u0003אמר להון\u0004 \u0005[להם\u0006\u0005]:\u0006 \u0003מחמת זקנה נשרו.\u0004","מספרים: \u0003ההוא דאיתחייב נגידא קמיה\u0004 \u0005[\u0006אדם אחד שעבר עבירה ושהתחייב מלקות לפני\u0005]\u0006 \u0003ר' אמי.\u0004 כאשר פשטו את בגדיו להלקותו \u0003איגלאי\u0004 \u0005[התגלה\u0006\u0005]\u0006 \u0003בית השחי\u0004 שלו, \u0003חזייה\u0004 \u0005[ראה אותו\u0006\u0005]\u0006 ר' אמי באותו אדם \u0003דלא מגלח\u0004 \u0005[שאינו מגלח\u0006\u0005]\u0006 את שיער בית השחי, \u0003אמר להון\u0004 \u0005[להם\u0006\u0005]\u0006 \u0003ר' אמי\u0004 לשמשיו: \u0003שיבקוה\u0004 \u0005[הניחו לו\u0006\u0005],\u0006 \u0003דין מן חבריא\u0004 \u0005[זה מן החברים\u0006\u0005]\u0006 \u0003הוא,\u0004 רואים שנוהג כמנהג חברים, שאינו עובר על איסור אף שאחרים אינם מקפידים עליו.","\u0003בעא מיניה\u0004 \u0005[שאל אותו\u0006\u0005]\u0006 \u0003רב מר' חייא: מהו\u0004 הדין \u0003לגלח\u0004 את שיער בית השחי? \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003אסור. אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003והא קא\u0004 \u0005[והרי הוא\u0006\u0005]\u0006 \u0003גדל\u0004 ומצער אותי! \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003בר פחתי\u0004 \u0005[בן אצילים\u0006\u0005],\u0006 \u0003זמן\u0004 מוגבל \u0003יש לו\u0004 לשיער, \u0003כל זמן שהוא גדל\u0004 מעבר לשיעורו — \u0003נושר,\u0004 ואין לחשוש שיגדל יותר מדי.","ועוד באותו ענין \u0003בעא מיניה\u0004 \u0005[שאל אותו\u0006\u0005]\u0006 \u0003רב מר' חייא: מהו לחוך\u0004 (לחכך), מותר לשפשף בידיו את שיער בית השחי כדי להשירו? \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003אסור.\u0004 שאל אותו: האם כשהוא משפשף לא במישרין אלא \u0003בבגדו, מהו\u0004 דינו? \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003מותר. איכא דאמרי\u0004 \u0005[יש שאומרים\u0006\u0005]\u0006 שלא כך היתה השאלה, אלא \u0003בעא מיניה\u0004 \u0005[שאל אותו\u0006\u0005]:\u0006 \u0003בתפלה בבגדו מאי\u0004 \u0005[מה\u0006\u0005]?\u0006 האם מותר לשפשף מקום זה דרך בגדו בזמן התפילה? \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003אסור.\u0004 ומעירים: \u0003ולית הילכתא כוותיה\u0004 \u0005[ואין הלכה כמותו\u0006\u0005]\u0006 בענין זה."],["במשנה הקודמת דובר בשני נזירים שנטמא אחד מהם ולא ידוע איזה הוא, והתבאר כיצד הם מביאים קרבנות טומאה וטהרה כאחד ויוצאים מידי ספק זה. ובמשנה זו דנים מה יעשו אם \u0003מת אחד מהן\u0004 לפני שהביאו את הקרבנות. \u0003אמר ר' יהושע: יבקש\u0004 הנזיר הנותר מ\u0003אחד מן השוק\u0004 (סתם אדם) \u0003שידור כנגדו בנזיר,\u0004 לפי התנאים שיתנה, כדי שיוכל להקריב עמו יחד.","\u0003ואומר\u0004 לו כך: \u0003אם טמא הייתי —\u0004 \u0003הרי אתה נזיר מיד, ואם טהור הייתי —\u0004 \u0003הרי אתה נזיר אחר שלשים יום. וסופרין\u0004 עתה שניהם \u0003שלשים\u0004 יום, \u0003ומביאין קרבן טומאה וקרבן טהרה. ואומר\u0004 הנזיר שהיה בו הספק: \u0003אם אני הוא\u0004 שהייתי \u0003הטמא —\u0004 \u0003קרבן טומאה שלי, וקרבן טהרה —\u0004 \u0003שלך. ואם אני הוא\u0004 שהייתי \u0003הטהור —\u0004 \u0003קרבן טהרה שלי, וקרבן טומאה\u0004 שהבאנו יהיה \u0003בספק.\u0004","\u0003וסופרים\u0004 עוד \u0003שלשים יום ומביאין קרבן טהרה, ואומר\u0004 אותו הנזיר שהיה בו הספק: \u0003אם אני\u0004 הייתי \u0003הטמא —\u0004 \u0003קרבן טומאה\u0004 שהבאנו בסוף השלושים הקודמים היה \u0003שלי, וקרבן טהרה\u0004 שהבאנו אז — היה \u0003שלך, וזה\u0004 שאני מביא כעת — הוא \u0003קרבן טהרתי\u0004 של עכשיו. \u0003ואם אני הוא הטהור\u0004 בין השניים שהיה בהם ספק הטומאה — \u0003קרבן טהרה שלי\u0004 היה, \u0003וקרבן טומאה\u0004 שהבאנו היה רק \u0003בספק, ו\u0004לפיכך \u0003זהו קרבן טהרתך\u0004 שלך.","\u0003אמר לו בן זומא: ומי שומע לו שידור כנגדו בנזיר?\u0004 איך אפשר ליצור הלכה על סמך שיימצא אדם אחר שיהיה מוכן לנדור נדר נזירות מתאים, בכל הימים הללו! \u0003אלא,\u0004 יש לו תקנה אחרת: \u0003מביא\u0004 לאחר שלושים ימי נזירות \u0003חטאת העוף ועולת בהמה, ואומר: אם טמא הייתי —\u0004 \u0003החטאת\u0004 היא \u0003מחובתי\u0004 כנזיר שנטמא, \u0003והעולה\u0004 היא קרבן \u0003נדבה\u0004 סתם. \u0003ואם טהור הייתי —\u0004 \u0003העולה מחובתי\u0004 כקרבן נזיר טהור, \u0003והחטאת\u0004 באה \u0003מספק.\u0004","\u0003וסופר שלשים יום\u0004 אחרים, \u0003ומביא קרבן טהרה, ואומר: אם טמא הייתי —\u0004 \u0003העולה הראשונה\u0004 שהבאתי תיחשב ל\u0003נדבה, וזו\u0004 שאני מביא כעת היא \u0003חובה. ואם טהור הייתי —\u0004 \u0003העולה הראשונה\u0004 שהבאתי עלתה לשם \u0003חובה\u0004 של נזירות טהרה, \u0003וזו\u0004 שאני מביא כעת \u0003נדבה, וזו,\u0004 שאר הקרבנות, החטאת והשלמים שהבאתי עכשיו — הם \u0003שאר קרבני,\u0004 קרבן הנזירות שצריך הייתי להביא קודם.","\u0003אמר ר' יהושע:\u0004 לפי שיטתך \u0003נמצא זה מביא קרבנותיו לחצאים,\u0004 שאם היה טהור, הרי הביא עולה לטהרתו תחילה, ורק לאחר שלושים יום הביא שאר הקרבן. \u0003אבל הודו לו חכמים לבן זומא\u0004 ואין חוששים לשיקול זה של הבאת קרבנות לחצאים.","שנינו שר' יהושע טען כנגד בן זומא שנמצא מביא קרבנותיו לחצאים, ושואלים: מה הפגם בכך? \u0003ולייתי\u0004 \u0005[ושיביא\u0006\u0005]\u0006 לחצאים! \u0003אמר רב יהודה אמר שמואל: לא אמר ר' יהושע\u0004 הערה זו משום שסבר שיש איסור בכך, \u0003אלא\u0004 כדי \u0003לחדד בה את התלמידים,\u0004 שיתעוררו הם להעיר כנגדו שאין פגם בכך.","\u0003אמר רב נחמן\u0004 בלשון מבודחת: \u0003מאי ליעביד ליה\u0004 \u0005[מה יעשה לו\u0006\u0005]\u0006 \u0003ר' יהושע לדקיה\u0004 \u0005[לבני המעיים\u0006 של הבהמות שלו\u0005]\u0006 ש\u0003לא ליסרו\u0004 \u0005[יסריחו\u0006\u0005],\u0006 שאם הוא סבור שצריך שיהיו קרבנות הטהרה כולם באים בבת אחת, הרי יצטרך להמתין שלושים יום בין קרבן לקרבן.","\u0003נזיר שהיה\u0004 ביום הראשון שנזר \u0003טמא בספק\u0004 שהוא ספק טמא טומאת מת, \u0003ו\u0004גם \u0003מוחלט בספק\u0004 שספק אם היה טמא טומאת צרעת. מה יעשה כדי לתקן חובות תגלחת של נזיר טהור וטמא של מצורע? — \u0003אוכל בקדשים אחר ששים יום\u0004 מזמן שנדר בנזירות, שרק אז יוצא לגמרי מידי ספק טומאת הצרעת.","שלאחר שלושים יום מגלח תגלחת ראשונה לתחילת טהרתו מן הצרעת, ולאחר שלושים יום מגלח תגלחת שניה — תגלחת ימי ספרו, ואז מותר באכילת קדשים, \u0003ו\u0004אולם \u0003שותה יין ומטמא למתים\u0004 לסיים נדר נזירותו רק \u0003אחר מאה ועשרים יום.\u0004 כי אולי היה קודם מצורע מוחלט, ותגלחות שעשה לשם צרעת אינן נחשבות לו לתגלחת לשם נזירות. ולכן לאחר שישים יום הראשונים צריך להמתין עוד שלושים יום לשם נזירות ומגלח. ועדיין אינו יוצא ידי חובתו, כי אולי היה טמא, ותגלחת זו שלאחר תשעים יום היתה לתגלחת טומאה, ולכן ינהג נזירות עוד שלושים יום, ולאחר מאה ועשרים יום מגלח ויוצא ידי חובת נזירות.","ומדוע לא יגלח מיד אחר שבעה ימים ראשונים לצרעתו, ותגלחת שניה לצרעתו אחר שבעה ימים נוספים — משום \u0003שתגלחת הנגע דוחה\u0004 את \u0003תגלחת הנזיר\u0004 רק \u0003בזמן שהוא\u0004 מצורע \u0003ודאי. אבל בזמן שהוא ספק\u0004 מצורע — \u0003אינו דוחה,\u0004 ולכן צריך להמתין לכל אחת מתגלחות הצרעת שלושים יום."],["\u0003תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 החכם: \u0003במה דברים אמורים\u0004 במשנה — \u0003בנזירות מועטת\u0004 של שלושים יום, \u0003אבל בנזירות בת שנה\u0004 כשהיה ספק טמא טומאת מת וספק מצורע מוחלט — \u0003אוכל בקדשים לאחר שתי שנים,\u0004","\u0003ושותה יין ומיטמא למתים לאחר ארבע שנים.\u0004","\u0003ותני עלה\u0004 \u0005[ושנינו עליה\u0006\u0005]\u0006 על הלכה זו שבמשנה כהסבר: \u0003ומגלח ארבע תגלחיות\u0004 (ארבע פעמים) וכל פעם באופן אחר ולשם ענין אחר. כיצד? \u0003תגלחת ראשונה\u0004 בסוף שלושים יום של נזירות סתם (או בסוף כל תקופת נזירות שנדר בה) \u0003מביא\u0004 שתי \u0003צפורים\u0004 של מצורע, שאחת נשחטת על מים חיים ואחת משולחת (ויקרא יד, ד-ז),","\u0003וחטאת העוף\u0004 לספק תגלחת טומאת נזירות, \u0003ועולת בהמה\u0004 לספק תגלחת טהרה. בתגלחת \u0003שניה מביא חטאת העוף ועולת בהמה, שלישית\u0004 גם כן \u0003מביא חטאת העוף ועולת בהמה, רביעית מביא קרבן טהרה.\u0004 ומעתה באים לבאר את פרטי הדברים וטעמיה.","\u0003אמרת\u0004 \u0005[אומר אתה\u0006\u0005]\u0006 בברייתא הזו: \u0003תגלחת ראשון מביא\u0004 צפורים וחטאת העוף ועולת בהמה. ומסבירים: בדרך זו, \u0003ממה נפשך שפיר קמייתי\u0004 \u0005[בכל אופן שתרצה יפה\u0006 הוא מביא\u0005],\u0006 \u0003דאי\u0004 \u0005[שאם\u0006\u0005]\u0006 \u0003ודאי מצורע הוא ולאו\u0004 \u0005[ולא\u0006\u0005]\u0006 \u0003טמא הוא\u0004 הרי \u0003ציפורין\u0004 שהוא מביא הם \u0003חובתו\u0004 להיטהר מן הצרעת, \u0003וחטאת העוף\u0004 שהוא מביא מספק שמא היה טמא — היא \u0003ספק,\u0004 ולכן \u0003אזלא\u0004 (הולכת) \u0003לקבורה\u0004 ככל חטאת העוף הבאה משום ספק, שאינה יכולה להיאכל. \u0003ועולה,\u0004 עולת העוף שמביא על צד שהיה נזיר טמא, \u0003הויא\u0004 \u0005[הריהי\u0006\u0005]\u0006 \u0003נדבה. ו\u0004מגלח תגלחת ראשונה של צרעת רק לאחר שלושים, כי","\u0003לגלחו\u0004 מיד \u0003תוך שבעה\u0004 לאחר שנטהר מצרעתו \u0003אי אפשר, דדילמא\u0004 \u0005[ששמא\u0006\u0005]\u0006 \u0003לאו\u0004 \u0005[לא\u0006\u0005]\u0006 מצורע \u0003מוחלט הוא\u0004 ואין עליו חובת תגלחת, והרי יש עליו נדר נזירות, \u0003ורחמנא אמר\u0004 \u0005[והתורה אמרה\u0006\u0005]\u0006 \u0003\"תער לא יעבר על ראשו עד מלאת\u0004 הימים אשר יזיר לה'","\u0003\"\u0004(במדבר ו, ה) ולכן אינו יכול לגלח עד סוף ימי הנזירות. וממשיכים לבאר צדדי הספק בקרבנות התגלחת הראשונה: \u0003ואי לאו\u0004 \u0005[ואם לא\u0006\u0005]\u0006 \u0003מצורע ודאי הוי\u0004 \u0005[הוא\u0006\u0005],\u0006 \u0003והוא טמא\u0004 ודאי בטומאת המת, אם כן \u0003חטאת העוף\u0004 שמביא היא \u0003חובתו\u0004 שמביא משום תגלחת נזיר טמא, \u0003וציפורין\u0004 של מצורע אין פגם בעשייתן כי \u0003אבראי קא מתעבדין\u0004 \u0005[בחוץ הם נעשים\u0006\u0005]\u0006 בין כה וכה ואינן קרבן, \u0003ולא הוי\u0004 \u0005[ואין הם\u0006\u0005]\u0006 בכלל איסור הבאת \u0003חולין בעזרה,\u0004 כך שאין כל עבירה במה ששוחט את הציפור בחוץ. \u0003ועולת בהמה הויא\u0004 \u0005[הריהי\u0006\u0005]\u0006 עולת \u0003נדבה.\u0004","\u0003ואי לאו\u0004 \u0005[ואם לא\u0006\u0005]\u0006 \u0003מצורע הוא ולאו\u0004 \u0005[ולא\u0006\u0005]\u0006 \u0003טמא הוא,\u0004 גם אז עושה כדין, כי \u0003ציפורין אבראי קא מתעבדין\u0004 \u0005[הצפורים בחוץ נעשות\u0006\u0005]\u0006 ואין בכך כל עבירה, \u0003חטאת העוף\u0004 הולכת \u0003לקבורה\u0004 שהרי ספק היא, \u0003עולת בהמה הויא\u0004 \u0005[הריהי\u0006\u0005]\u0006 \u0003חובתו\u0004 כנזיר שמשלים ימי נזירותו. ושואלים: \u0003והא בעי\u0004 \u0005[והרי צריך\u0006\u0005]\u0006 המצורע להביא \u0003אשם\u0004 בתוך קרבנותיו, על מנת להשלים כפרתו ולהתירו לאכילת קדשים! ומשיבים: שיטת \u0003ר' שמעון היא, דאמר\u0004 \u0005[שאומר\u0006\u0005]:\u0006 \u0003מייתי ומתני\u0004 \u0005[מביא\u0006 אדם אשם ומתנה\u0005]\u0006 ואומר כך: אם חייב הוא — הרי זה לחובתו, ואם לא — הרי הוא שלמי נדבה.","\u0003תגלחת שניה ושלישית ציפורין לא צריך\u0004 להביא עוד, \u0003דהא עביד\u0004 \u0005[שהרי\u0006 כבר עשה\u0005],\u0006 \u0003מאי איכא\u0004 \u0005[מה יש\u0006\u0005]\u0006 מקום לחשוש — \u0003דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003ודאי מוחלט הוא\u0004 קודם לכן, ומשום כך \u0003חדא\u0004 \u0005[\u0006חטאת אחת\u0005]\u0006 מן העוף שמביא בתגלחת השניה — הרי זה \u0003לספק ספרו,\u0004 שאם היה מצורע מוחלט, הרי לאחר טהרה ראשונה צריך שוב לספור שבעה ימים (וכאן, מספק — שלושים יום) ולהביא חטאת,","\u0003וחדא\u0004 \u0005[\u0006וחטאת אחת\u0005]\u0006 שמביא בתגלחת שלישית, הרי זה \u0003לספק טומאתו.\u0004 שאם היה מצורע, הרי הקרבנות שהביא בתגלחות הקודמות היו לצורך תקנת טהרתו הגמורה מצרעת, ולא עלו לנזירותו, ולפיכך אם היה טמא הרי צריך להביא עכשיו חטאת כנזיר שנטמא. ועולת בהמה שמביא בתגלחת שניה ושלישית — על צד שנזיר טהור היה. \u0003תגלחת רביעית מביא קרבן טהרה ומתני\u0004 \u0005[ומתנה\u0006\u0005],\u0006"],["\u0003ו\u0004כך הוא מתנה, ש\u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003ודאי נזיר הוא\u0004 מתחילה, שלא היה טמא לא בטומאת מת ולא בצרעת, \u0003עולה הראשונה\u0004 שהביא לאחר תגלחת ראשונה היתה לשם \u0003חובה\u0004 של נזירות טהרה, \u0003וזו\u0004 שמביא כעת היא \u0003נדבה. ואם טמא ומוחלט הוא\u0004 מתחילה, נמצא כי \u0003עולה הראשונה\u0004 שהביא היתה \u0003נדבה, וזו\u0004 שמביא עכשיו היא \u0003חובה, וזה\u0004 קרבנות אחרים שמביא עכשיו, אשם ושלמים, הם \u0003שאר קרבנו.\u0004","עד כאן לגבי המקרה שדובר בו במשנה. ומעתה יידונו מקרים דומים. נזיר שהיה \u0003טמא\u0004 טומאת המת מ\u0003ספק, ו\u0004מצורע \u0003מוחלט ודאי —\u0004 \u0003אוכל בקדשים לאחר שמונה ימים,\u0004 שסופר שבעה ימים, ולאחר מכן נטהר מטומאת הצרעת, וביום השמיני מביא קרבנותיו, ומותר לאכול אז קדשים. \u0003ושותה יין ומיטמא למתים לאחר ששים ושבעה ימים,\u0004 שצריך לספור עוד שלושים יום לנזירותו ומגלח, ואחר כך סופר עוד שלושים יום, שמא התגלחת הקודמת היתה תגלחת טומאתו, וזו היא נזירות טהרתו.","ועוד מקרה: נזיר שהיה \u0003מוחלט ספק וטמא ודאי —\u0004 \u0003אוכל בקדשים לאחר שלשים ושבעה ימים,\u0004 שמגלח לאחר שבעה ימים משום טומאה ודאי, ומתחיל למנות שלושים ימי נזירות מחדש. ובסוף ימי הנזירות הללו מגלח שוב ואז הוא טהור מספק טומאת הצרעת ואוכל בקדשים. \u0003ו\u0004אולם \u0003שותה יין ומיטמא למתים לאחר שבעים וארבעה ימים,\u0004 כי שמא היה מצורע מוחלט וטמא, ושתי תגלחות ראשונות (של שבעה ושל שלושים ושבעה) עלו לו רק לטהרת מצורע בחלוטו ובספירתו, וצריך לספור עוד שלושים יום לנזירות טהרה.","ועוד מקרה: נזיר שהיה \u0003טמא ודאי ומוחלט ודאי —\u0004 \u0003אוכל בקדשים לאחר שמונה ימים\u0004 שמגלח מיד תגלחת ראשונה של צרעתו, ומונה שבעה ימים ומגלח שוב לצרעתו, ולמחרת אוכל בקדשים. \u0003ושותה יין ומיטמא למתים לאחר ארבעים וארבעה ימים,\u0004 שמונה שבעה ימים נוספים של גידול שיער לתגלחת טומאתו ומגלח, ומונה שלושים יום לתגלחת טהרתו.","\u0003שאלו תלמידיו את ר' שמעון בן יוחי: נזיר טהור ו\u0004הוא גם \u0003מצורע, מהו שיגלח תגלחת אחת\u0004 \u0003ועולה\u0004 (תיחשב) \u0003לו לכאן ולכאן,\u0004 כלומר גם לצורך תגלחת הצרעת וגם לצורך תגלחת הנזירות? \u0003אמר להן: אינו מגלח.\u0004","\u0003אמרו לו: למה? אמר להן: אילו\u0004 מהות שתי התגלחות היתה שווה, ש\u0003זה לגדל\u0004 שיער \u0003וזה לגדל\u0004 שיער, \u0003ו\u0004כן \u0003זה להעביר\u0004 שיער \u0003וזה להעביר\u0004 שיער — \u0003יפה אתם אומרים. עכשיו\u0004 מהות שתי התגלחות היא שונה, \u0003נזיר\u0004 מגלח — כדי \u0003להעביר\u0004 את שערו, \u0003ומצורע\u0004 — כדי \u0003לגדל\u0004 שיוכל שוב לגלח לאחר ימי ספרו.","ושאלו עוד התלמידים: \u0003ו\u0004אף אם \u0003לא תעלה לו\u0004 תגלחת נזירות \u0003ל\u0004תגלחת של סוף \u0003ימי חלוטו, ו\u0004אולם עדיין \u0003תעלה לו\u0004 תגלחת שבסוף \u0003ימי ספרו,\u0004 ששוב אינו צריך לגלח, ואינה אלא להעביר את השיער! \u0003ואמר להן: אילו זה\u0004 היה נעשה \u0003לפני זריקת דמים וזה לפני זריקת דמים —\u0004 \u0003יפה אתם אומרים, אלא מצורע\u0004 מגלח \u0003לפני זריקת דמים\u0004 של הקרבן, \u0003ונזיר לאחר זריקת דמים\u0004 ואין דמיון מוחלט ביניהן.","ועוד שאלו אותו: \u0003ולא תעלה לו לימי צרעתו ונזירותו, ותעלה לו\u0004 לפחות \u0003לימי צרעתו\u0004 לתגלחת \u0003טומאתו\u0004 ששתיהן לפני זריקת דמים! \u0003אמר להן: אילו זה\u0004 מגלח \u0003לפני ביאת מים,\u0004 כלומר, לפני שטובל, \u0003וזה לפני ביאת מים —\u0004 \u0003יפה אתם אומרים. אלא\u0004 נזיר \u0003טמא\u0004 מגלח \u0003לאחר ביאת מים, מצורע —\u0004 \u0003לפני ביאת מים.\u0004","\u0003אמרו לו: יפה אמרת שלא תעלה לו\u0004 תגלחת אחת \u0003לימי ספרו ולנזירותו. ו\u0004אולם נאמר ש\u0003תעלה לו\u0004 לפחות \u0003לימי חלוטו וטומאתו,\u0004 ש\u0003זה לגדל וזה לגדל הוא!\u0004","\u0003אמר להן:\u0004 בכל אופן שהוא אין דמיון מלא בין תגלחת נזיר ותגלחת מצורע. שאם \u0003נזיר טהור והוא מצורע\u0004 יש הבדל ביניהם כי \u0003זה\u0004 מצורע \u0003לגדל\u0004 שיער, \u0003וזה\u0004 נזיר טהור \u0003להעביר\u0004 שיער \u0003ואם נזיר טמא והוא מצורע\u0004 יש הבדל אחר — \u0003זה\u0004 מצורע \u0003לפני ביאת מים וזה\u0004 נזיר טמא \u0003לאחר ביאת מים.\u0004"],["\u0003תני\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003ר' חייא\u0004 אותם דברים עצמם: אין תגלחת צרעת עולה גם לתגלחת נזירות, שכן \u0003זה,\u0004 המצורע, מגלח \u0003לפני ביאת מים (חיים) וזה,\u0004 נזיר טמא, \u0003לאחר ביאת מים, זה,\u0004 מצורע, מגלח \u0003לפני זריקת דמים וזה,\u0004 נזיר טהור, \u0003לאחר זריקת דמים.\u0004","שנינו במשנה: \u0003\"שתגלחת הנגע\" וכו'. בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רמי בר חמא: הני\u0004 \u0005[אותן\u0006\u0005]\u0006 \u0003ארבע תגלחיות דקאמר\u0004 \u0005[שהוא אומר\u0006\u0005]\u0006 שצריך הנזיר לגלח מפני הצרעת והטומאה, האם כולן \u0003משום מצוה\u0004 לגלח, \u0003או\u0004 שמא יש בהן שאינה מצוה, אלא \u0003משום אעבורי\u0004 \u0005[העברת,\u0006 הסרת\u0005]\u0006 \u0003שיער\u0004 שגדל ב\u0003טומאה\u0004 כדי לגדל שיער אחר?","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן\u0006\u0005]\u0006 אם עושה זאת מטעם זה או זה? ומסבירים: לענין \u0003לעבורי בנשא\u0004 \u0005[להעביר,\u0006 להסיר את השיער בסם\u0005],\u0006 \u0003אי אמרת\u0004 \u0005[אם אומר אתה\u0006\u0005]\u0006 שהטעם הוא \u0003משום מצוה,\u0004 אם כן \u0003לעבורי בנשא\u0004 \u0005[להעביר בסם\u0006\u0005]\u0006 \u0003לא\u0004 יועיל, כיון שיש מצוה מיוחדת לגלח, \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר\u0006\u0005]\u0006 שהטעם \u0003משום אעבורי\u0004 \u0005[העברת\u0006\u0005]\u0006 \u0003שיער טומאה —\u0004 \u0003אפילו סכיה נשא נמי\u0004 \u0005[סך אותו בסם גם כן\u0006\u0005]\u0006 מועיל.","ואם כן, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 תשובה לשאלה זו ממה ששנינו במשנה: \u0003ומגלח ארבע תגלחיות. אי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 \u0003משום עבורי\u0004 \u0005[העברת\u0006\u0005]\u0006 \u0003שיער טומאה —\u0004 \u0003אפילו בשלש נמי סגיא ליה\u0004 \u0005[גם כן די לו\u0006\u0005],\u0006 שתיים משום צרעת, והאחרונה לסוף נזירות הטהרה, ואילו השלישית, שאינה אלא כדי להתחיל ולמנות נזירות טהרה בלא שיער טומאה — מדוע נמנית בכללן? \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי כולן \u0003משום מצוה\u0004 של תגלחת הוא. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכן הוא. \u0003הגויים אין להם נזירות,\u0004 שאין דין נזירות חל עליהם, אינם אסורים באיסורי הנזיר ואין מקבלים מהם קרבן אם הביאו בסוף נזירותם. \u0003נשים ועבדים\u0004 כנענים \u0003יש להן נזירות. חומר\u0004 (חומרה) \u0003בנשים מבעבדים —\u0004 \u0003שהוא,\u0004 האדון, אם רוצה בכך, \u0003כופה את עבדו\u0004 שנדר בנזיר לשתות יין או לגלח שערו ולהיטמא למתים, \u0003ואינו כופה את אשתו\u0004 לעבור על נדר נזירותה.","","","\u0003קתני\u0004 \u0005[שנה\u0006\u0005]:\u0006 \u0003הגויים אין להם נזירות,\u0004 נשים ועבדים יש להם נזירות. \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו\u0006\u0005]?\u0006 \u0003דתנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]\u0006 נאמר בתחילת פרשת נזירות \u0003\"דבר אל בני ישראל\"\u0004 (במדבר ו, ב) ויש בכך הדגשה למיעוט — \u0003ולא לגויים.\u0004 ומה שנאמר \u0003\"ואמרת אליהם\u0004 איש או אשה \u0003\"\u0004— הרי זה בא \u0003לרבות את העבדים.\u0004 ושואלים: \u0003למה לי קרא\u0004 \u0005[כתוב\u0006\u0005]\u0006 מיוחד לרבות את העבדים? \u0003האמרת\u0004 \u0005[הרי אומר אתה\u0006\u0005]\u0006 כלל בהלכה: \u0003כל מצוה שהאשה חיבת בה\u0004 — גם \u0003עבד חייב בה,\u0004 וכשם שנשים בכלל נזירות, אף עבדים בכללה!","\u0003אמר רבא: שאני הכא\u0004 \u0005[שונה כאן\u0006\u0005]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 בדיני נדרים \u0003\"לאסר אסר על נפשו\"\u0004 (שם ל, ג) ודרשו חכמים: דבר זה נאמר דווקא \u0003במי שנפשו קנויה לו\u0004 שעומד ברשות עצמו, \u0003יצא עבד שאין נפשו קנויה לו,\u0004 שהרי הוא משועבד לאדוניו. ומשום כך היינו אומרים \u0003הואיל ואין נפשו\u0004 של עבד \u0003קנויה לו —\u0004 \u0003אימא גבי\u0004 \u0005[אמור שאצל\u0006\u0005]\u0006 דין \u0003נזיר נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא\u0004 יוכל לנדור, למרות שבדרך כלל הוקש דין העבד לדין האשה, ואשה היא בכלל נזירות. על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 כתוב מיוחד שרשאי הוא להזיר. וחוזרים לדון בתחילת דרשת הכתובים.","\u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 \u0003\"דבר אל בני ישראל\" —\u0004 \u0003ולא לגויים.\u0004 ושואלים: \u0003וכל היכא דכתיב\u0004 \u0005[מקום שכתוב\u0006\u0005]\u0006 בתורה \u0003\"ישראל\", גויים לא\u0004 בכלל זה? \u0003והא גבי\u0004 \u0005[והרי אצל\u0006\u0005]\u0006 דיני \u0003ערכין, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 שם \u0003\"דבר אל בני ישראל\"\u0004 (ויקרא כז, ב) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003בני ישראל מעריכין\u0004 (מקדישים בערכים) \u0003ואין הגויים מעריכין,\u0004 ואם אמר \"ערך פלוני עלי\" — לא התחייב כלל.","\u0003יכול לא יהו נערכין,\u0004 כלומר, שגם אם אמר ישראל \"ערכו של פלוני הגוי עלי\" גם כן לא יתחייב — \u0003תלמוד לומר:\u0004 לריבוי \u0003\"איש\u0004 כי יפליא נדר בערכך\u0003\"\u0004 (שם), לומר שאף סתם \"איש\" שאינו מישראל, בכלל דיני ערכין הוא לענין זה. והרי אף בנזיר נאמר \"איש כי יפליא\" (במדבר שם), ואם כן נרבה גם גויים לענין איסורי נזירות!","ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן\u0006\u0005]\u0006 בדין נזירות ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"לאביו ולאמו לא יטמא\"\u0004 (במדבר ו, ז), משמע שמצוה זו נאמרה דווקא \u0003במי שיש לו אב, יצא גוי שאין לו אב\u0004 שאין הוא נחשב כמתייחס אחר אביו. ושואלים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 אין אב לגוי? \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 \u0003לענין ירושה —\u0004 \u0003והאמר\u0004 \u0005[והרי אמר\u0006\u0005]\u0006 \u0003ר' חייא בר אבין אמר ר' יוחנן: גוי יורש את אביו דבר\u0004 (מדין) \u0003תורה, שנאמר: \"כי ירשה לעשו נתתי את הר שעיר\"\u0004 (דברים ב, ה)!","\u0003אלא\u0004 הכוונה היא \u0003במי שמוזהר על כיבוד אביו,\u0004 וגוי אינו מצווה על כך, והריהו כמי שאין לו אב. ומקשים: \u0003מי כתיב\u0004 \u0005[האם כתוב\u0006\u0005]\u0006 \u0003\"כבד אביך\" גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר?\u0004 ואם כן, מה ענין זה לזה? \u0003אלא\u0004 כך צריך להבין את הלימוד מאותו פסוק: \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 לגבי נזיר \u0003\"לאביו ולאמו\u0004 לאחיו ולאחותו \u0003לא יטמא\"\u0004 (במדבר שם) לומר: \u0003במי שיש לו\u0004 דין \u0003טומאה\u0004 הכתוב מדבר,"],["\u0003יצא גוי שאין לו טומאה,\u0004 שאינו נטמא אף אם נגע במת, שאינו בכלל נזירות. ושואלים: \u0003מנלן דלית להו\u0004 \u0005[מניין לנו שאין להם\u0006 לגויים\u0005]\u0006 \u0003טומאה?\u0004 — ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 בדינו של הנכנס למקדש כשהוא טמא \u0003\"ואיש אשר יטמא ולא יתחטא ונכרתה הנפש ההוא מתוך הקהל\"\u0004 (במדבר יט, כ) ומכאן למדים שדין טומאה נוהג רק \u0003במי שיש לו קהל, יצא זה\u0004 הגוי \u0003שאין לו קהל,\u0004 שהרי איננו שייך לקהל ישראל.","ושואלים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 יודע אתה מהכתוב הזה שאין בו דין טומאה כלל? \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003כרת הוא\u0004 ש\u0003לא מיחייב\u0004 \u0005[מתחייב\u0006\u0005]\u0006 על כניסתו למקדש כשהוא טמא, \u0003אבל איטמויי מיטמו\u0004 \u0005[להיטמא נטמאים\u0006 הם\u0005]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"והזה הטהר על הטמא\"\u0004 (במדבר יט, יט), לומר: \u0003כל שיש לו\u0004 אפשרות של \u0003טהרה\u0004 מטומאתו על ידי מי חטאת — \u0003יש לו טומאה, וכל שאין לו טהרה —\u0004 \u0003אין לו טומאה.\u0004","ומקשים, \u0003ואימא\u0004 \u0005[ואמור\u0006\u0005]:\u0006 \u0003טהרה הוא דלא הויא ליה\u0004 \u0005[שאין לו\u0006\u0005]\u0006 אבל \u0003טומאה הויא ליה\u0004 \u0005[יש לו\u0006\u0005]!\u0006 ומשיבים: לכן \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"ואיש אשר יטמא ולא יתחטא\"\u0004 (במדבר יט, כ) — ללמד ששני הדברים תלויים זה בזה, ומי שאין לו טהרה במי החטאת, אף אין לו דין טומאה.","\u0003רב אחא בר יעקב אמר\u0004 הסבר אחר לכך שאף שבנזיר, כמו בערכין, נאמר \"איש\" והיה מקום לרבות גוי לנזירות, אין הוא בכלל נזירות. \u0003שאני הכא\u0004 \u0005[שונה כאן\u0006\u0005]\u0006 בדין נזירות, שנאמר בו איסור טומאה לאביו ולאמו, ובענין זה אין הגוי שייך, משום ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"והתנחלתם אתם לבניכם אחריכם\"\u0004 (ויקרא כה, מו) לומר:","\u0003כל\u0004 מי \u0003שיש לו\u0004 בנים לענין ירושת \u0003נחלה\u0004 שיכול להוריש לבניו כל סוגי ירושה, ובכלל זה עבדים, \u0003יש לו\u0004 דין אבהות ביחס לאותם בנים אף לענין \u0003טומאה, וכל שאין לו נחלה —\u0004 \u0003אין לו\u0004 דין אב לענין \u0003טומאה,\u0004 ולכן הגוי שאינו בכלל האפשרות לרשת עבדים מאביו — אף אינו בכלל טומאה לאביו, ולכן אין הוא גם בכלל נזירות, שנאמר בה \"לאביו ולאמו לא יטמא\". ומקשים: \u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005]\u0006 \u0003עבדים נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא\u0004 יהיה להם דין טומאה, וממילא גם דין נזירות, שהרי אין להם נחלה וירושה!","\u0003אלא אמר רבא:\u0004 יש לחזור ולפתור את השאלה, במה שונה דין הגויים בנזירות מערכין, למרות שבשניהם נאמר \"איש\", באופן אחר. \u0003בשלמא גבי\u0004 \u0005[נניח אצל\u0006\u0005]\u0006 דין \u0003ערכין שנאמר\u0004 בפרשת ערכין בתורה \u0003\"\u0004דבר אל \u0003בני ישראל\"\u0004 (ויקרא כז, ב) אנו למדים: \u0003בני ישראל מעריכין ואין הגוים מעריכין, יכול לא יהו נערכין —\u0004 \u0003תלמוד לומר: \"איש (איש)\"\u0004 (ויקרא כז, ב).","אבל \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 בענין נזירות, אם רוצה אתה לומר שגויים בכלל נזירות, איך תדרוש בדרך זו? מ\"בני ישראל\" תלמד כי \u0003בני ישראל נוזרין ומביאין קרבן ואין הגוים נוזרין ומביאין קרבן.\u0004 ומן המלה \"איש\" תאמר: \u0003יכול אף לא יהו נזירין כלל —\u0004 \u0003תלמוד לומר \"איש\"\u0004 לרבות?","הרי \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]\u0006 בתשובה על כך: \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003משום קרבן לאו מהכא נפקא ליה\u0004 \u0005[לא מכאן יוצא,\u0006 נובע, לו הדבר\u0005],\u0006 \u0003אלא מהתם\u0004 \u0005[משם\u0006\u0005]\u0006 מכתוב אחר, שנאמר \u0003\"\u0004איש איש מבית ישראל ומן הגר בישראל אשר יקריב קרבנו לכל נדריהם ולכל נדבותם אשר יקריבו לה' \u0003לעלה\"\u0004 (ויקרא כב, יח) — \u0003פרט ל\u0004קרבן \u0003נזירות\u0004 שאין הגוי מקריב, אלו \u0003דברי ר' יוסי הגלילי!\u0004 ואם כן מה שנאמר \"בני ישראל\" בנזירות לא למעט קרבן בא שהרי כבר נתמעטו מכך הגויים, אלא למעט כל עיקרה של הנזירות.","ושואלים: עדיין ניתן ללמוד שגוי שייך בנזירות, \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 ודרוש כך את הכתובים: הכתוב \"דבר אל בני ישראל\" (במדבר ו, ב), מלמד ש\u0003בני ישראל נוזרין נזירות עולם —\u0004 \u0003ואין הגוים נוזרים נזירות עולם, יכול לא יהו נזירים\u0004 כלל — \u0003תלמוד לומר: \"איש\"\u0004 (במדבר ו, ב)! \u0003אמר ר' יוחנן: מי כתיב\u0004 \u0005[האם נאמר\u0006\u0005]\u0006 בכתוב \u0003\"נזיר עולם\"?\u0004 \"נזיר\" סתם נאמר, והכתוב ממעט גויים מכל דין נזירות, וכל סוג.","ומקשים עוד, \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 כך את דרשת הכתוב: \u0003בני ישראל\u0004 מיוחדים בנזירות לפי שהם \u0003מדירין בניהם\u0004 הקטנים \u0003בנזיר, ואין הגוים מדירין בניהם בנזיר, יכול לא יהו נזירים\u0004 בעצמם — \u0003תלמוד לומר: \"איש\"!\u0004 ומשיבים, \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 \u0003ר' יוחנן: הלכה\u0004 למשה מסיני \u0003היא בנזיר\u0004 שהאב מדיר את בנו, ואינו כתוב במקרא, ובודאי לא בא הכתוב למעט אותו.","ומקשים עוד, \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 כך: \u0003בני ישראל\u0004 יש להם דין מיוחד בנזירות שהם \u0003מגלחין על\u0004 קרבנות \u0003נזירות אביהן ואין הגוים מגלחין על נזירות אביהן.\u0004"]]};
